var e={id:`genesis`,name:`创世记 50 天`,shortName:`创世记`,totalDays:50,startDate:`2026-07-13`,weeklyCount:10,finalMinDays:30,scriptureVersion:`新标点和合本`,banner:`创世记 50 天 · 灵修同行`,domain:`genesis-50.pages.dev`},t=[{key:`weekly_1`,type:`weekly`,name:`同行 · 第 1 周`,subtitle:`创造之初`,icon:`🌱`,cardEnabled:!0},{key:`weekly_2`,type:`weekly`,name:`同行 · 第 2 周`,subtitle:`方舟与虹`,icon:`🌈`,cardEnabled:!0},{key:`weekly_3`,type:`weekly`,name:`同行 · 第 3 周`,subtitle:`蒙召起行`,icon:`⛺`,cardEnabled:!0},{key:`weekly_4`,type:`weekly`,name:`同行 · 第 4 周`,subtitle:`应许之子`,icon:`✦`,cardEnabled:!0},{key:`weekly_5`,type:`weekly`,name:`同行 · 第 5 周`,subtitle:`抓取者摔跤`,icon:`🤝`,cardEnabled:!0},{key:`weekly_6`,type:`weekly`,name:`同行 · 第 6 周`,subtitle:`归回本家`,icon:`🏔`,cardEnabled:!0},{key:`weekly_7`,type:`weekly`,name:`同行 · 第 7 周`,subtitle:`被卖异乡`,icon:`⛓`,cardEnabled:!0},{key:`weekly_8`,type:`weekly`,name:`同行 · 第 8 周`,subtitle:`同囚与解梦`,icon:`🌙`,cardEnabled:!0},{key:`weekly_9`,type:`weekly`,name:`同行 · 第 9 周`,subtitle:`荒年到丰年`,icon:`🌾`,cardEnabled:!0},{key:`weekly_10`,type:`weekly`,name:`同行 · 第 10 周`,subtitle:`一家族恢复`,icon:`🛡`,cardEnabled:!0},{key:`story_create`,type:`story`,name:`创造篇 · 神看为美好`,subtitle:`创世记 1-11`,icon:`🌍`,cardEnabled:!0},{key:`story_abraham`,type:`story`,name:`亚伯拉罕篇 · 蒙召与应许`,subtitle:`创世记 12-25`,icon:`⭐`,cardEnabled:!0},{key:`story_jacob`,type:`story`,name:`雅各篇 · 摔跤与和解`,subtitle:`创世记 26-36`,icon:`🌀`,cardEnabled:!0},{key:`story_joseph`,type:`story`,name:`约瑟篇 · 一家族恢复`,subtitle:`创世记 37-50`,icon:`🕊`,cardEnabled:!0},{key:`behavior_return`,type:`behavior`,name:`「从今天继续」印`,subtitle:`中断后回来，比从不间断更重要`,icon:`👣`,cardEnabled:!1,ruleHidden:!0,encouragement:`你又回来了。这一步，比从不停下更难。`},{key:`behavior_truth`,type:`behavior`,name:`「真实的话」印`,subtitle:`诚实比完整更重要`,icon:`💧`,cardEnabled:!1,ruleHidden:!0,encouragement:`你今天说了一句真实的话。神听见真实的你。`},{key:`behavior_step`,type:`behavior`,name:`「今日一步」印`,subtitle:`小、清楚、可以完成`,icon:`🪨`,cardEnabled:!1,ruleHidden:!0,encouragement:`你迈出了今天的一步。小小的，但真实的。`},{key:`behavior_weekend`,type:`behavior`,name:`「周末仍同行」印`,subtitle:`在可以停下的日子，仍选择回来`,icon:`🛐`,cardEnabled:!1,ruleHidden:!1,encouragement:`周末你仍回来了。同行不分日子。`},{key:`final_companion`,type:`final`,name:`50 天同行者`,subtitle:`真实走过，与神也与同伴同行`,icon:`🏆`,cardEnabled:!0,encouragement:`你走完了 50 天。不是完美，而是真实。愿这段同行的脚踪被记念。`}],n={id:`hebrews`,name:`希伯来书 30 天`,shortName:`希伯来书`,totalDays:30,startDateEnv:!0,weeklyCount:6,finalMinDays:18,scriptureVersion:`圣经新译本`,banner:`希伯来书 30 天 · 灵修同行`,domain:`hebrews-30.pages.dev`},r=[{key:`weekly_1`,type:`weekly`,name:`同行 · 第 1 周`,subtitle:`儿子的超越`,icon:`🌱`,cardEnabled:!0},{key:`weekly_2`,type:`weekly`,name:`同行 · 第 2 周`,subtitle:`进入安息`,icon:`🏞`,cardEnabled:!0},{key:`weekly_3`,type:`weekly`,name:`同行 · 第 3 周`,subtitle:`灵魂之锚`,icon:`⚓`,cardEnabled:!0},{key:`weekly_4`,type:`weekly`,name:`同行 · 第 4 周`,subtitle:`信心的见证人`,icon:`⭐`,cardEnabled:!0},{key:`weekly_5`,type:`weekly`,name:`同行 · 第 5 周`,subtitle:`管教中站稳`,icon:`🔥`,cardEnabled:!0},{key:`weekly_6`,type:`weekly`,name:`同行 · 第 6 周`,subtitle:`不能震动的国`,icon:`🏔`,cardEnabled:!0},{key:`story_son`,type:`story`,name:`儿子 · 神借着祂说话`,subtitle:`来 1-4:13`,icon:`☀`,cardEnabled:!0},{key:`story_priest`,type:`story`,name:`大祭司 · 体恤软弱`,subtitle:`来 4:14-7`,icon:`🕍`,cardEnabled:!0},{key:`story_covenant`,type:`story`,name:`新约 · 已开的新路`,subtitle:`来 8-10`,icon:`📜`,cardEnabled:!0},{key:`story_faith`,type:`story`,name:`信心的忍耐 · 仰望耶稣`,subtitle:`来 11-12:17`,icon:`🛤`,cardEnabled:!0},{key:`story_kingdom`,type:`story`,name:`不能震动的神国`,subtitle:`来 12:18-13`,icon:`👑`,cardEnabled:!0},{key:`behavior_return`,type:`behavior`,name:`「从今天继续」印`,subtitle:`中断后回来，比从不间断更重要`,icon:`👣`,cardEnabled:!1,ruleHidden:!0,encouragement:`你又回来了。这一步，比从不停下更难。`},{key:`behavior_truth`,type:`behavior`,name:`「真实的话」印`,subtitle:`诚实比完整更重要`,icon:`💧`,cardEnabled:!1,ruleHidden:!0,encouragement:`你今天说了一句真实的话。神听见真实的你。`},{key:`behavior_step`,type:`behavior`,name:`「今日一步」印`,subtitle:`小、清楚、可以完成`,icon:`🪨`,cardEnabled:!1,ruleHidden:!0,encouragement:`你迈出了今天的一步。小小的，但真实的。`},{key:`behavior_weekend`,type:`behavior`,name:`「周末仍同行」印`,subtitle:`在可以停下的日子，仍选择回来`,icon:`🛐`,cardEnabled:!1,ruleHidden:!1,encouragement:`周末你仍回来了。同行不分日子。`},{key:`final_companion`,type:`final`,name:`希伯来书同行者`,subtitle:`真实走过，与神也与同伴同行`,icon:`🏆`,cardEnabled:!0,encouragement:`三十天，你走完了。不是完美，而是真实。`}],i=JSON.parse(`[{"day":1,"chapter":1,"title":"在末后的日子借着儿子说话的神","key_verses":"来 1:1-4","story_section":"儿子","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》没有交代作者的姓名和收信人的地区。它劝勉那些因逼迫和生活艰难而疲惫的信徒，要跟随耶稣到底。作者重新讲明神已经借着儿子赐下的话语，以此坚固他们的信心。古时，神借着先知多次用不同的方式说话；如今，他借着儿子耶稣，清楚显明自己的旨意和我们当走的路。因此，信徒应当以耶稣的教导作为信仰和生活的准则。\\n\\n末后的日子，指神借着儿子说话、开启救恩道路的时期。耶稣显明神的荣耀和旨意，以大能的话语托住万有，洁净了罪以后，就坐在神的右边。神借着这位儿子使我们认识他，带领我们走向救恩。学习耶稣的教导，像他一样顺服神、爱邻舍，就是跟随神的道路。\\n\\n当时的犹太社会普遍盼望圣殿和以色列完全复兴。人们期待有洁净的圣殿、有权威的祭司，再建立一个强盛的国家，神的统治就会清楚显明。作者尊重先知和圣殿的传统，同时宣告：信徒现在需要聆听的，是神已经借着儿子说的话。即使仍在等候圣殿和国家复兴，也应当遵行耶稣的教导。神所喜悦的生活，已经在耶稣所教导并活出的爱与顺服中清楚显明。\\n\\n信徒需要继续学习并实践已经听过的耶稣之道。人越不安，越容易被那些声称掌握特殊秘密、提供强力解决办法的人吸引。这时，更应察验所听的教导是否与耶稣的话一致。耶稣教导我们行公义、怜悯受苦的人，甚至爱仇敌。信徒顺服自己所明白的话语，就能在不确定的处境中继续跟随耶稣。\\n\\n即使身处不安的时代，神也没有把我们丢在沉默中。他已经借着儿子指明当走的路。我知道，你们正努力按这教导忠心生活。你们用心听默想分享的书信，在小组中一同查考圣经，并努力顺服所明白的话语，我为你们的付出深深感恩。我们还有不足，却不必因此怀疑一路走来的信仰，灰心丧气。在我们学习和顺服的过程中，神会补足我们的缺欠，使我们更加成熟。我盼望你们因这份确信重新得力。让我们信靠在我们中间作工的神，继续像现在这样，一同跟随耶稣生活。","prayer":"天父，感谢您借着儿子向我们说话。感谢您使这些弟兄姊妹用心聆听默想分享，在小组中学习您的话，努力顺服。我们仍有不足，求您这位知道他们心意和辛劳的父亲亲自补足。不要让他们因自己的缺欠而灰心，求您使他们信靠在我们中间作工的您，继续跟随耶稣。愿我们一同学习时，对您的话有更深的领悟；每天顺服时，爱心和诚实也不断成长。也求您使我成为与他们一同学习、顺服，并不断鼓励他们的牧者。阿们。"},"handbook":{"today_focus":"神已经借着耶稣清楚指明生命的道路。在众多声音中，信仰首先要问的不是\\"什么最强、最快、最吸引人\\"，而是\\"什么符合耶稣关于公义、怜悯和爱人的教导\\"。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"经文怎样描述神过去和如今说话的方式？"},{"question":"1:2-3用了哪些话说明儿子的身份和工作？"}],"meditations":[{"question":"最近最影响我选择的声音是什么：惧怕、对成功的追求、别人的评价，还是耶稣的话？","hint":""},{"question":"哪一项主张或建议，需要放在耶稣关于公义、怜悯和保护弱者的教导下重新分辨？","hint":""},{"question":"我已经在哪一件小事上守住了诚实和爱？今天可以为此怎样感谢神？","hint":""}],"practices":["慢慢读一遍耶稣的一段教导，并写下我今天要如何按照这段教导作出选择。","不必追逐更新奇的答案；先把已经明白的一件事活出来。"],"prayer":"感谢神没有让我们留在沉默和混乱中。\\n求主使我在复杂的声音中认出耶稣的道路。\\n求主赐我勇气，把明白的真理化为具体的顺服。"}},{"day":2,"chapter":1,"title":"高过天使的儿子","key_verses":"来 1:5-14","story_section":"儿子","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第1章引用《诗篇》和《撒母耳记下》，说明儿子耶稣为什么高过天使。在当时的犹太传统中，天使是传达神的话、参与颁布律法的尊贵使者。作者把这些受人尊敬的天使与儿子相比较。神称耶稣为儿子，赐他君王的权柄；天使则受托承担服役的工作。信徒应当聆听并跟随的，是神所立的儿子耶稣。\\n\\n儿子的治理公义而不改变。经文说，他喜爱公义，恨恶不法；天使则是奉差遣服事将要承受救恩之人的灵。作者说明这区别，是要信徒承认耶稣的权柄，顺服他的话。神交托给儿子的统治，是建立公义、除去不法的治理，并非用恐惧控制人的权力。信徒应当按耶稣的教导分辨是非，并照着去行。\\n\\n在盼望圣殿和以色列复兴的热潮中，人们期待宏伟的圣殿、有权威的祭司和强大的宗教秩序能实现神的统治。承受外在压力的信徒，也想从看得见的制度和民族力量中寻找安全。《希伯来书》劝他们持守神借着儿子赐下的话，跟随到底。即使制度强大、群体壮大，实践耶稣的教导仍是信徒的责任。神国显明在那些顺服耶稣的公义与爱的人所过的生活中。\\n\\n今天，我们也应当先察验传道人所讲的内容是否符合耶稣的教导，而不是只看他的学历或社会成就。传道人服事信徒，帮助他们理解并顺服神的话；信徒则把所听的与圣经对照，一同提问、讨论，分辨其中的意思。在彼此学习中，我们纠正误解，寻找落实在生活中的途径。当我们尊重预备信息之人的辛劳，也认真聆听彼此的疑问，群体就会在一同跟随耶稣的信心中成长。\\n\\n我们群体的传道人，并不是凭着显赫学历或卓越的社会成就而受人认可。他们却努力在耶稣基督里忠实传讲神的旨意。小组中也有许多弟兄姊妹用心预备、分享神的话，我为他们的付出深深感恩。你们并不盲从某一个人的意见，而是一同查考圣经、提出问题，分辨神话语的意思。看见你们彼此学习，我十分喜乐。即使还有不明白的地方，也请不要有压力，继续参与分享。让我们认真聆听彼此的疑问，以所领受的话语互相鼓励，在需要的时候也凭爱心劝勉。我也愿意与你们一同学习，越来越像耶稣基督。","prayer":"天父，感谢您借着耶稣教导、治理我们。感谢您赐下传讲信息的人，以及预备小组分享的弟兄姊妹。求您赐他们智慧和力量，使他们准确理解您的话，忠实传讲。愿我们都认真聆听彼此，一同查考圣经，分辨耶稣的心意。愿提问的人和教导的人都受到尊重，也都把所领受的话落实在生活中。求您使我与信徒一同学习、彼此建立，让我们的群体在鼓励和劝勉中越来越像耶稣。阿们。"},"handbook":{"today_focus":"耶稣高过一切看得见和看不见的权威。真正显明他治理的，不是组织的规模或领袖的声势，而是人的尊严是否被维护、软弱者是否得到保护、群体是否被带向公义和爱。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"作者引用了哪些旧约经文来说明儿子与天使的不同？"},{"question":"经文怎样描写儿子的国度和治理？"}],"meditations":[{"question":"我是否把某位领袖、某种制度、组织规模或特殊经历看得过于绝对？","hint":""},{"question":"我手中的权力、经验或资源，正在使谁得益？又可能压住了谁的声音？","hint":""},{"question":"当我被忽视时，\\"耶稣高过一切权威\\"给我怎样的尊严和安慰？","hint":""}],"practices":["认真听完一位平时不容易被听见之人的意见。","肯定一份无人看见的服事，并具体表达感谢。"],"prayer":"感谢主的权柄是公义、怜悯并使人得生命的。\\n求主纠正我对人的权威和成功的迷恋。\\n求主帮助我用手中的影响力扶持软弱的人。"}},{"day":3,"chapter":2,"title":"更加留心所听的道 免得随流失去","key_verses":"来 2:1-4","story_section":"儿子","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》说明儿子高过天使以后，随即劝勉我们更加留心已经听过的话（2:1）。随流失去，指人在不再留心神的话时，渐渐远离原先跟随耶稣的生活。日子忙碌，难处接连而来，我们很容易听了道，却把遵行的话推到以后。作者唤醒信徒，不要任凭自己停留在这种状态。我们要记住所听的话，把它落实在今天的选择中，彼此鼓励，继续跟随耶稣。\\n\\n经文所说的伟大救恩，是耶稣亲自宣讲、听见的人传给我们，并有神以能力和圣灵的恩赐作见证的救恩（2:3--4）。我们遵行耶稣的话，脱离罪和死亡的辖制，过爱神、爱邻舍的生活，最终进入神所应许的生命与荣耀。珍惜救恩的人，会继续走这条路。诚实工作、承担责任、照顾有需要的邻舍，都属于这样的顺服。即使为未来感到不安，也要抓住今天可以实践的话语。\\n\\n作者的论证十分清楚：违背借着天使传达的话，尚且不能逃避责任，我们就更应珍惜并顺服儿子所传的救恩。这警告要信徒继续按已经领受的话前行，并非让他们停留在恐惧中。当时，人们想从圣殿和国家复兴中寻找安全，但信徒应当持守的，仍是从耶稣所学的道路。今天，我们也不能因担忧将来，就推迟眼前可以作出的顺服。一同学习神的话、彼此帮助，会使我们在艰难中继续走信心的路。\\n\\n亲爱的弟兄姊妹，我知道，即使处境艰难，你们仍在耶稣基督里，按神的旨意忠心前行。不过，想到那些因经济困难而为将来忧虑的人，我仍十分挂念。对未来的焦虑一旦加重，连眼前能做的事也可能无心去做。耶稣教导我们不要忧虑明天（马太福音6:34），就是要我们承担今天的责任，信靠明天仍会看顾我们的神。我也愿意聆听你们的难处，与你们一同寻找出路。让我们持守从默想和讲道中学到的耶稣教导，把今天能做的事一件件做好，倚靠神，一同向前走。","prayer":"天父，感谢您保守这些弟兄姊妹，使他们在艰难中仍按您的话前行。求您记念那些因经济困难和前途不明而心里沉重的人，尤其是为工作和生活担忧的弟兄姊妹。求您赐他们平安，不因明天的忧虑耗尽心力，以致错过今天该做的事；也赐他们智慧和力量，明白眼前应当承担的责任。愿他们持守从默想和讲道中学到的耶稣教导，今天也诚实工作、彼此帮助。求您使我认真聆听他们的忧虑，与他们一同寻找所需的帮助，让我们都信靠您，稳步向前。阿们。"},"handbook":{"today_focus":"远离信仰常常不是一次公开的背叛，而是在忙碌、失望和孤立中慢慢发生。察觉自己正在漂流，不是定罪自己的理由，而是重新校正方向、恢复联系的机会。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"\\"随流失去\\"的画面让你想到怎样的危险？"},{"question":"经文为什么说我们更应当留心所听见的道？"}],"meditations":[{"question":"最近什么事情像水流一样不断推着我走，使我难以听见耶稣的话？","hint":""},{"question":"我是否正一点一点远离读经、祷告或互相信任的关系？原因是什么？","hint":""},{"question":"群体中是否有人变得沉默、疏远，需要一句没有压力的问候？","hint":""}],"practices":["今天读一小段耶稣的话，不求多，只求重新停在主面前。","若独自难以站稳，把自己的近况告诉一位可靠的人。"],"prayer":"求主让我及时看见自己的方向。\\n求主除去羞耻和自责，使我愿意重新回来。\\n求主使我们的群体温柔地接纳那些疲惫、被人疏远或正逐渐远离群体的人。"}},{"day":4,"chapter":2,"title":"与我们同有血肉的弟兄","key_verses":"来 2:5-18","story_section":"儿子","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第2章引用《诗篇》第8篇，说明神赐给人的尊荣和责任。神把照管、治理受造世界的工作交托给人。然而，我们现在还看不见万物都服在人之下，仍经历罪和死亡带来的痛苦。作者就在这样的现实中，引导我们仰望耶稣。耶稣与我们同有血肉，经历苦难和死亡，神却赐给他荣耀和尊贵。他称受苦的我们为弟兄姊妹，带领我们走上救恩的道路。\\n\\n神使耶稣借着苦难，完成带领人得救的使命（2:10）。耶稣亲身经历人的痛苦，仍顺服神到底。经文说明，他在各方面与弟兄相同，成为满有怜悯、忠信的大祭司（2:17）。正因为亲自受过苦、经历过试探，他能帮助今天受试探的人（2:18）。因此，信徒在艰难中可以倚靠耶稣的帮助，借着这位深知我们痛苦的主来到神面前，继续走神所引导的路。\\n\\n这番话给当时受苦的信徒带来极大的安慰。他们起初领受神的话时，曾满怀喜乐地决定跟随耶稣，也热心走在这条路上。然而，同族的犹太人把跟随耶稣的他们视为异端，将他们排除在群体之外。他们因而失去了原有的人际支持和维持生计的互助关系，生意和生活日渐艰难，持守信仰甚至成了危及生计的严峻考验。作者提醒他们，耶稣正是为他们受苦的。他来是要传明神的旨意，带领人得救；在传讲这些话的过程中，他受尽苦楚，最终死在十字架上。信徒可以倚靠这位深知他们痛苦的耶稣。这份安慰，今天也赐给正在经历难处的你们。\\n\\n耶稣如今仍在神的右边为我们代求。亲爱的弟兄姊妹，我不轻看你们生活中的艰难和心里的重担。但我们有一位深知我们痛苦、为我们祈求的耶稣。神会怜悯你们，引导你们走更好的路。我盼望你们因这份确信得着安慰，重新得力。让我们把忧虑和挂念交给神，忠心做好今天的工作，照顾家庭。信靠那位看顾我们的神，一同前行，你们会在这条路上经历他的引导。","prayer":"天父，感谢您差遣耶稣，使他体恤并帮助受苦的我们。我们倚靠如今仍为我们代求的耶稣，把这些弟兄姊妹交托给您。求您安慰因经济压力和人际关系而疲惫的心，使他们确信您正在怜悯、引导他们，因而重新得力。愿他们把忧虑交给您，忠心做好工作，照顾家庭，继续与弟兄姊妹相交。求您开出所需的道路，赐下彼此帮助的智慧。也求您使我与他们分担重担，让我们都在日常生活中经历您的引导。阿们。"},"handbook":{"today_focus":"耶稣没有远离人的身体、痛苦和死亡，而是进入其中，成为我们的弟兄。他的同在使我们不必假装坚强，也呼召群体停止轻率解释苦难，转而真实陪伴受苦的人。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"经文怎样说明耶稣与\\"儿女\\"同有血肉？"},{"question":"耶稣经历苦难，对受试探的人有什么意义？"}],"meditations":[{"question":"我是否习惯隐藏自己的软弱，担心被看作信心不足？","hint":""},{"question":"面对受苦的人，我是否急着解释、劝告，却没有先听清他的需要？","hint":""},{"question":"我可以怎样尊重对方的选择、界限和恢复的速度？","hint":""}],"practices":["向一位可靠的人说明自己真实需要的帮助。","陪伴受苦者时，先问\\"你现在最需要什么\\"，并把回答听完。"],"prayer":"感谢耶稣真实进入人的痛苦。\\n求主让我不再因软弱而羞耻。\\n求主赐我耐心和尊重，能负责任地陪伴受苦的人。"}},{"day":5,"chapter":3,"title":"在神的家中尽忠的儿子","key_verses":"来 3:1-6","story_section":"儿子","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》劝我们仔细思想耶稣，并把他与摩西相比较。摩西是向以色列传达律法、带领他们走过旷野的领袖。他作为仆人，在神的家中忠心履行所托付的工作。耶稣也忠于神交托的使命，但他是管理这家的儿子。作者肯定摩西的忠心，同时指出，信徒最终应当信靠、跟随的，是儿子耶稣。\\n\\n摩西以仆人的身份，为神将来要说的事作见证；耶稣则以儿子的身份管理、带领神的家。尊重摩西和律法的信徒，应当清楚这一区别。他们不能因为困难，就离开耶稣，回到熟悉的宗教秩序中，而应当听从神所立之子的教导，跟随到底。带领教会的人，也应当顺服耶稣的话，服事信徒。\\n\\n这里神的家，指属于神的子民。作者说\\"我们就是他的家了\\"，并劝信徒持守盼望和坦然无惧的心[（3:6，《新译本》）](https://www.bible.com/zh-CN/bible/41/HEB.3.6.CNVS)。当时，盼望圣殿和以色列复兴的人，把心放在看得见的建筑和制度上。然而，那些遵行耶稣的话、持守盼望的信徒，本身就是神的家。教会中的每一个人，都是这个家里宝贵的一员。\\n\\n既然耶稣管理神的家，任何人都不能把教会当作自己的产业。信徒应当像一家人那样彼此照顾，忠心承担各自的责任。教导神的话、预备饭食、耐心聆听和鼓励别人，都是建立群体的服事。比起角色的大小或显眼的成果，更重要的是怀着向神忠心的心彼此服事。一同持守盼望的信心，正是在这些日常的付出中显明出来。\\n\\n我感谢神，我们中间没有人把群体当作自己的产业，绝大多数弟兄姊妹也在不同岗位上热心服事教会。我没有听说有人因为自己的角色小，就推卸责任。有人在忙碌中抽空服事敬拜团队，有人在小组里带领查经，或积极参与讨论。到了主日，有人一早预备饭食，也有人默默承担清洁。我为你们每一个人的付出深深感恩。我们知道，这教会属于神，我们都是其中的家人，所以愿意按神所赐的恩赐谦卑服事。盼望你们珍惜彼此的辛劳，继续传承这美好的传统。","prayer":"天父，感谢您使这些弟兄姊妹像一家人那样服事您的教会。求您记念那些在忙碌中预备敬拜、分享话语、做饭和清洁的人。即使他们的付出不容易被看见，也求您加添喜乐和力量。愿他们不因岗位看似微小，就忘记自己是家中宝贵的一员；也愿他们看见彼此的辛劳，常存感谢。求您使我珍惜每一个人的服事，与大家一同延续这美好的传统，按所领受的恩赐，谦卑建立教会。阿们。"},"handbook":{"today_focus":"神的家首先不是建筑，而是属于耶稣、彼此守望的百姓。耶稣是家主，因此领袖不能把群体当成自己的产业，每个人也都不是多余的。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"摩西在神的家中是什么身份？儿子又是什么身份？"},{"question":"经文用什么条件描述\\"我们就是他的家\\"？"}],"meditations":[{"question":"我是否独占某项角色，不愿分享信息、机会或决定权？","hint":""},{"question":"我是否因为自己的角色不显眼，就轻看自己已经承担的责任？","hint":""},{"question":"有哪些长期而不被看见的照顾和承诺，值得我今天感谢神？","hint":""}],"practices":["把一项可以分享的责任、经验或机会交给别人。","具体肯定一个人在群体中长期默默承担的劳苦。"],"prayer":"感谢主使我们成为神的家。\\n求主保守领袖不把群体当作自己的私有产业。\\n求主使每个人都找到忠心参与、彼此建立的位置。"}},{"day":6,"chapter":3,"title":"今天听见他的声音","key_verses":"来 3:7-19","story_section":"儿子","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第3章引用《诗篇》第95篇，回顾旷野那一代人的失败。以色列人经历过从埃及蒙拯救的恩典，却在旷野遭遇困难时不再信靠神，违背他的话，最终因不顺服而未能进入应许的安息。作者劝勉信徒，不要重蹈覆辙，不要硬着心，而要听从神。\\n\\n经文强调的时刻，是今天。《希伯来书》把《诗篇》的话传给信徒，视为圣灵此刻向他们所说的话（3:7）。即使过去经历过恩典、宣认过信仰，今天也不能拒绝神的话。我们应当持守起初的信心到底，天天彼此劝勉。回应了神呼召的子民，也要继续按这呼召生活。\\n\\n有人说，口里承认就能得救；也有人说，相信耶稣为我死在十字架上就能得救。我不否定这些话，却不能把它们理解为，只要作出信仰告白，无论生活态度和行为如何，都能得救。把这些话与今天的经文一同读，就会明白原因。以色列人在埃及为奴时，神借着摩西呼召他们成为自己的子民。神拯救他们，并非因为他们有什么功劳。他先以恩典呼召，以色列人则回应了这呼召。他们遵从神的话，冒着生命危险离开埃及，把心里的决定化为行动。他们能走出埃及，完全是出于神的恩典。\\n\\n然而，旷野生活一长，以色列人便埋怨、不满，不再顺服神，最终未能进入安息之地迦南。《希伯来书》的读者也处在仿佛行经旷野的境地。他们相信耶稣是神差来传达旨意的那一位，也曾顺服他；但困难持续，信心便开始动摇。我想请大家思想：救恩的道路只靠口头宣认就能继续走下去，还是要蒙召的子民顺服前行？请把口里承认这句话放在受逼迫的处境中思想。当掌权者威胁说：\\"你相信耶稣是神差来的吗？若是这样，你就难逃一死！\\"一个人仍然承认这信仰，其中包含了冒死跟随耶稣的选择。我们不能忽略这样的处境，把经文的一部分抽出来，理解成与生活无关的口头告白。\\n\\n亲爱的弟兄姊妹，我并不认为你们轻看神的话。你们也各自在走自己的旷野：生养孩子的辛劳、接连加班的工作、夫妻之间的伤害，以及父母催促结婚的期待，都使每一天不容易度过。你们虽不完美，仍在坚守信仰、忍耐前行，我十分珍惜这份付出。让我们坦诚把苦楚告诉神，却不要因埋怨而远离他的话。倚靠神所赐的智慧和能力，今天也一同走顺服的路。","prayer":"天父，感谢您以恩典呼召我们，今天仍用话语引导我们。求您看顾养育孩子、工作到深夜，以及因夫妻伤害和家人期待而辛苦的弟兄姊妹。求您记念他们持守信仰的努力，加添所需的智慧和能力。愿他们不隐藏心里的苦楚，坦诚向您倾诉，也不因埋怨而远离您的话。求您使我们口里的宣认，继续成为今天的顺服；也使我与他们分担重担，以爱心鼓励他们。阿们。"},"handbook":{"today_focus":"\\"今日\\"表示神现在仍在呼唤，也表示回应的机会仍然存在。心的刚硬往往在长期防御、拒绝倾听和拖延顺服中形成；彼此劝勉则是在爱中陪人重新回到信靠和顺服。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"诗篇95篇中的旷野世代为什么没有进入安息？"},{"question":"作者吩咐群体怎样防备罪的迷惑？"}],"meditations":[{"question":"我心里是否有一处因为受伤或失望，已经拒绝再听任何劝勉？","hint":""},{"question":"哪一件道歉、求助或改正，我一直推到\\"以后\\"？","hint":""},{"question":"我劝勉别人时，是先了解他的处境，还是急着要求结果？","hint":""}],"practices":["从一件拖延已久的道歉、求助或改正开始。","劝勉一个人以前，先问清楚他的处境和承受能力。"],"prayer":"感谢神今天仍向我说话。\\n求主软化我因伤害而封闭的心。\\n求主教我以爱说诚实的话，也给人改变所需的时间。"}},{"day":7,"chapter":4,"title":"那仍然存留的安息","key_verses":"来 4:1-11","story_section":"儿子","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第4章告诉我们，进入神安息的应许如今仍然存留。神完成创造以后，在第七天安息。以色列人走过旷野、进入迦南，却不表示神的安息已经完全实现。在约书亚之后，神仍借着《诗篇》呼唤人，今天就回应他的声音。作者据此说明，信徒仍应盼望神的安息，向着这应许前行。\\n\\n神的安息，是信靠并顺服神的人最终要享有的生命与平安，也就是救恩的完成。《希伯来书》说，旷野那一代人因为不信，未能进入安息；而他们的不信，正表现在不遵从神话语的行为中。相信神，就是信任他的话，并且实际遵行。今天的顺服，是朝着神所应许的安息迈出的一步。\\n\\n当时的信徒期待神的应许在圣殿和以色列国家的复兴中实现。作者却劝他们按耶稣的话生活，竭力进入神所应许的安息（4:11）。等候安息的人，不应重蹈旷野世代不顺服的覆辙，而要现在就聆听神的话，离开错误的道路，在困难中继续顺服。这劝勉既有警告，也有盼望，因为今天回应神的话、回到他面前的路，仍然敞开。\\n\\n今天的经文也教导我们，通往完全救恩、进入安息的路，是顺服的路。这是向那些心被圣殿复兴运动吸引、忽略耶稣教导的人发出的爱心警告：不要投身极端民族主义运动，要按已经领受的耶稣之道生活。即使曾经离开神的话，仍有回转的机会，所以现在就当恢复顺服的生活。我相信，我们的弟兄姊妹中，几乎没有人被其他邪教迷惑，或长期无视神的话。当然，我们偶尔仍会受诱惑，想按自己的心意生活。我也会有这样的念头，虽然并不常有。我们不能阻止一切诱惑出现。耶稣也受过试探，却宣告自己要按神的话生活，并且坚持到底，进入神为他预备的安息。亲爱的弟兄姊妹，你们正忠心走过旷野，盼望你们再鼓起一点勇气。面对上司的无礼，以神所赐的智慧应对；面对配偶令人费解的态度，以耶稣的温柔回应。教会服事的担子沉重时，也像耶稣那样借着祷告得力。在你们所走的顺服道路上，神的赐福与安息必与你们同在。","prayer":"天父，感谢您赐给我们安息的应许。求您坚固那些在旷野般的日常生活中，仍努力遵行耶稣话语的弟兄姊妹。当我们想随自己的意思生活时，求您使我们记起您的话，选择顺服。工作中遭遇无礼时，求您赐下智慧；与配偶相处时，赐下温柔；教会服事令人疲惫时，求您使我们借着祷告重新得力。愿远离您话语的人再次回转，也愿我体谅信徒的辛劳，与他们同行。求您使我们都信靠您的应许，稳步走向安息。阿们。"},"handbook":{"today_focus":"神的安息既是将来救恩完全实现的应许，也是今天顺服时可以预尝的生命和平安。竭力进入安息，不是增加宗教负担，而是拒绝刚硬，在信靠中实行神的旨意。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"作者把创造、旷野、约书亚和\\"今日\\"怎样连在一起？"},{"question":"第3-4章怎样把不信与不顺服联系起来？"}],"meditations":[{"question":"我是否把安息只理解成轻松、没有问题，或暂时停止工作？","hint":""},{"question":"今天哪一项顺服能让我预尝神所赐的生命和平安？","hint":""},{"question":"我的身体和心是否已经需要休息？我能否在不逃避责任的情况下安心休息？","hint":""}],"practices":["定下一件今天可以实行的顺服。","若已经疲惫，为休息真正留出时间，并把结果交托给神。"],"prayer":"感谢神仍为我们存留安息的应许。\\n求主使我的信心落实为顺服。\\n求主教我在责任与休息之间作诚实的分辨。"}},{"day":8,"chapter":4,"title":"显明人心的神之道","key_verses":"来 4:12-13","story_section":"儿子","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》4章12节宣告，神的话是活的，有能力。前文所传的安息应许，以及对不顺服的警告，今天仍然有效。神借着这些话，要求我们今天就相信并顺服。读到旷野世代失败的信徒，也应反省自己的生活。我们不能只知道过去发生了什么，更要决定现在怎样回应所听见的话。\\n\\n神的话像锋利的刀，意思是神准确辨明人的思想和意图。我们可以为自己的行为找出听来合理的理由，神却知道，那是出于信心的顺服，还是逃避责任的借口。即使把经文解释得对自己有利，也不能改变神的判断。因此，我们应当借着神的话看清自己的实际光景，承认错误。\\n\\n经文提到魂与灵、关节与骨髓，说明神知道人里面最深的地方。不只外在的行为，连内心的思想和动机，也都显露在他面前。即使别人看不出来，神也知道我们相信什么、怀着怎样的心行动。信徒不能只在意别人怎样看自己，而应诚实省察：自己的心和生活，是否遵从神的话？\\n\\n13节说明，所有人都要在神面前为自己的生活交账。过去的信仰经历和外表的宗教活动，不能掩盖今天的不顺服。神察看的是，我们现在是否信靠、遵行他的话。既然看见自己的错误，就当悔改，不再辩解。这段话并非许可我们随意判断别人的内心，而是劝我们亲自回应神的话，也帮助走远了的弟兄姊妹重新回来。\\n\\n亲爱的弟兄姊妹，今天的信息，是那些疏于聚会、远离受洗时所立心志，并轻看在基督里彼此劝勉的人应当认真听的。我今天不能只对他们说没关系，用这样的话安慰他们，因为我不能按自己的意思改动神清楚的吩咐。他们需要听见这话，悔改回来。我这样劝勉，是盼望他们重新按神的话生活。我们也不要在心里定他们的罪，而应为他们的恢复祷告，寻求神的智慧，凭爱心劝勉。盼望我们都尽好这责任，让走远了的弟兄姊妹再次与我们一同走信心的路。","prayer":"天父，我们来到您面前，您知道我们的心，也知道我们的生活。求您使那些远离受洗时所立心志、疏于聚会和彼此劝勉的弟兄姊妹，重新留心您的话。求您赐他们勇气，承认错误、悔改，再次顺服。也求您使我不因想安慰人，就把您的话说得含糊不清，而是凭爱心和诚实劝勉。愿我们为他们的恢复祷告，分享所需的帮助，不急于定罪；也愿我们温暖地迎接回转的人，一同走信心的路。阿们。"},"handbook":{"today_focus":"神的话没有停留在古老记录中；它今天仍显明神的旨意和审判标准。经文不是给我们用来剖析和定罪别人，而是使每个人在那位鉴察人心的神面前，为自己的回应负责。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"经文用哪些形象说明神话语的力量？"},{"question":"第13节把一切受造之物放在谁的面前？"}],"meditations":[{"question":"我是否常用经文先寻找别人的错误，而避开自己的回应？","hint":""},{"question":"哪一件已经明白的顺服，我仍在找借口拖延？","hint":""},{"question":"想到神知道我的动机并要我负责，我感到什么：惧怕、诚实、盼望，还是别的？","hint":""}],"practices":["不要勉强挖掘所有隐藏动机；先改正一件已经清楚知道的事。","分享经文时，用\\"我要怎样回应\\"代替对别人内心的判断。"],"prayer":"求神使我诚实来到他话语面前。\\n求主显明我需要回转的地方，也赐下回转的路。\\n求主保守我不滥用经文去定罪别人。"}},{"day":9,"chapter":4,"title":"体恤我们软弱的大祭司","key_verses":"来 4:14-16","story_section":"大祭司","letter":{"body":"亲爱的弟兄姊妹：\\n\\n旧约中的大祭司，代表百姓来到神面前。《出埃及记》第28章规定，要在大祭司所穿以弗得的肩带和胸牌宝石上，刻上以色列众子的名字。大祭司带着这些名字，在神面前记念百姓。到了赎罪日，他按《利未记》第16章的规定，穿上圣洁的细麻衣，带着祭牲的血进入至圣所，为自己和百姓赎罪。大祭司就是这样在神面前，服事有罪、有软弱的百姓。\\n\\n《希伯来书》说，耶稣是我们尊荣的大祭司。他已经来到天上的神面前，也为我们开通了亲近神的道路。因此，信徒应当持守已经宣认的信仰（4:14）。我们不必等到圣殿和祭司制度再次强盛，现在就可以倚靠耶稣来到神面前，寻求怜悯和恩典。\\n\\n耶稣体恤我们的软弱。他也经历过苦难和试探，却没有向罪屈服，而是顺服神。因此，他明白那些在艰难处境中动摇的信徒，能够帮助他们。作者劝我们倚靠这位耶稣，坦然来到施恩的宝座前（4:16），诚实告诉神我们的难处，寻求此刻所需的怜悯和帮助。这劝勉，今天也给了在旷野般的日常生活中前行的我们。\\n\\n面对不公正的上司，与婚后和恋爱时判若两人的配偶相处，承担教会服事、照顾父母，有时都像走旷野一样艰难。单靠自己的力量，我们会不堪重负，甚至想要放弃。《希伯来书》的作者体谅这样的信徒，向他们传递盼望：我们有帮助我们的耶稣。他是带领我们亲近神、领受恩典的中保。《罗马书》8章34节说，在神右边的耶稣正在为我们代求。他在神的右边，说明他与神最为亲近。正因为这位耶稣为我们代求，我们能靠神的恩典走过眼前的旷野。亲爱的弟兄姊妹，不要停留在失望、绝望和埋怨中。让我们默想神的话，来到神面前。我恳切盼望你们在这样的时刻，领受神的安慰和鼓励，重新得着前行的力量。","prayer":"天父，感谢您知道我们的软弱，借着耶稣向我们施恩。求您安慰那些因职场的不公、夫妻关系的难处、教会服事和照顾父母而疲惫的弟兄姊妹。愿他们把独自难以承担的重担向您倾诉，倚靠为我们代求的耶稣。求您使他们默想话语时得到安慰和鼓励，重新获得前行的力量。也求您使我认真听他们的处境，与他们一同寻找所需的帮助，让我们都在您的恩典中走过今天的旷野。阿们。"},"handbook":{"today_focus":"耶稣既代表我们来到神面前，也真实体恤人的软弱。他所开的恩典之路，不是让人逃避责任，而是使人能够说出真相、求怜悯、得帮助，并重新走上顺服的路。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"经文怎样同时描述耶稣的尊贵和他对软弱之人的体恤？"},{"question":"我们被邀请以怎样的态度来到施恩的宝座前？"}],"meditations":[{"question":"我是否认为自己必须祷告得好、表现得好，才配来到神面前？","hint":""},{"question":"哪一种惧怕、失败或诱惑，我一直隐藏，不敢求帮助？","hint":""},{"question":"我怎样对待别人向我说出的软弱：急着解决，还是守密并实际帮助？","hint":""}],"practices":["把一件一直隐藏的惧怕或错误诚实告诉神。","必要时向一位可靠的人提出具体的帮助请求。"],"prayer":"感谢耶稣体恤我的软弱。\\n求主赐我承认错误、拒绝诱惑和重新顺服的力量。\\n求主使我成为一个能守密、能扶持人的同伴。"}},{"day":10,"chapter":5,"title":"在苦难中顺从到底的主","key_verses":"来 5:1-10","story_section":"大祭司","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第5章说明，大祭司从百姓中被选出来，代表他们向神献上礼物和祭物。因为大祭司自己也有软弱，所以应当温柔对待无知或走入歧途的人。他也需要为自己的罪献祭。大祭司的职分，并非人自行争取的荣耀，而是像亚伦那样，蒙神呼召而承担的工作。\\n\\n耶稣也没有为自己取得荣耀，而是蒙神呼召成为大祭司。他虽是儿子，仍亲身经历人的痛苦。他大声呼求、流泪祷告，恳求那位能救他脱离死亡的神。他没有隐藏痛楚，而是坦诚向神倾诉；即使在这样的处境中，仍遵行神的旨意到底。顺服和祈求，在他的生命中一同显明。\\n\\n耶稣在苦难中学会顺从，意思是他亲身经历苦难，把顺服实行到底。[《新译本》在5章9节](https://www.bible.com/zh-CN/bible/41/HEB.5.9.CNVS)用\\"顺从到底\\"来表达这使命的完成。耶稣经历苦难和死亡，完成了带领人来到神面前的大祭司使命。5章7节说，他的祈求蒙了应允；13章20节则说明，神使耶稣从死人中复活。耶稣经历过死亡，神却使他重新活过来。祷告的应允，并不是让他避开死亡，而是使他胜过死亡。\\n\\n耶稣成为所有顺从他之人得到永远救恩的根源（5:9）。信徒跟随耶稣，顺服神的话，在艰难中向神祈求，就在这样的道路上有分于他的救恩。顺服，就是像耶稣那样，在实际生活中遵行神关于爱与公义的旨意。即使失败，也要回到神的话面前，再次顺服。在苦难持续、仍等候祷告蒙应允的时候，也应倚靠神，继续前行。\\n\\n今天的经文也教导我们怎样经历救恩。耶稣在苦难中顺服、祈求，神就救他脱离死亡。耶稣成为救恩的根源，意味着我们也跟随他，顺服神的话、向神祈求，经历神的拯救。这与前面所学进入安息的道路彼此相连。我们中间似乎有人祷告多次，却迟迟看不见期待的结果，因此感到失望。他们没有放弃顺服，只是越来越觉得遵行神的旨意很吃力，责任感多过喜乐。基督徒的生活不只在教会里，也包括成为好丈夫、好妻子，在工作中尽责，并富有创意。亲爱的弟兄姊妹，如果你知道该做什么，却缺少承担的喜乐和力量，盼望你借着祷告，与神有更深的相交。愿你在神里面重新得力，怀着耶稣的心，喜乐地继续走这条路。","prayer":"天父，感谢您借着在苦难中顺服、祷告的耶稣，为我们开启救恩的道路。求您顾念那些祷告之后仍长久等候、心已疲惫的弟兄姊妹。有些人努力顺服，却感到责任多于喜乐，求您使他们在祷告中与您深深相交，重新得力。愿夫妻彼此相爱，在职场上忠诚尽责、富有创意，在每天的生活中体贴耶稣的心。也求您使我与他们一同忍耐等候，常常鼓励他们，让我们都带着您所赐的喜乐，走顺服的路。阿们。"},"handbook":{"today_focus":"耶稣的顺服不是没有眼泪和恐惧，而是在真实的痛苦中仍然顺服神，始终遵行他赐人生命、彰显爱与公义的旨意。《希伯来书》也把顺服耶稣与永远的救恩直接相连。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"耶稣在受苦时怎样祷告？"},{"question":"\\"学了顺从\\"\\"得以完全\\"在这一段中指向什么？"}],"meditations":[{"question":"我是否把顺服误解为压住情绪、假装不痛？","hint":""},{"question":"即使付出代价，我今天必须守住哪一项诚实或保护哪一个人？","hint":""},{"question":"我已经在哪一段艰难中坚持了很久？我能否承认这也是信心的忠诚？","hint":""}],"practices":["把难以承担的事和真实情绪告诉神。","写下一个即使有代价也要实行的顺服，并寻求必要的支持。"],"prayer":"感谢耶稣在眼泪中顺服到底。\\n求主使我不逃避痛苦，也不放弃神的旨意。\\n求主记念并坚固我在艰难中已经走过的忠心道路。"}},{"day":11,"chapter":5,"title":"不要让聆听真道的耳朵迟钝","key_verses":"来 5:11-6:3","story_section":"大祭司","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》的作者正要进一步说明麦基洗德和耶稣的大祭司职分，却暂时停了下来，因为听众已经不再用心领受神的话。这不是说他们智力不足，或没有能力理解难懂的内容，而是说，他们听道多年，却渐渐迟钝，不愿用所听的话分辨现实并作出顺服。信主时间长，并不会自动使人成熟；把所听的道用在实际选择上，分辨力才会成长。\\n\\n这个群体起初曾忍受羞辱和损失，坚守信仰的道路。但难处持续太久，他们已经疲惫。当圣殿和以色列的复兴看起来更加安全、有力时，他们需要重新聆听耶稣是大祭司的意义，也要重新决定向谁忠心。因此，麦基洗德并不是一个只为增添高深知识而讨论的题目。作者借着他说明，来到神面前的道路，为什么不受利未血统和眼前圣殿制度的限制。\\n\\n奶和干粮的比喻，并非按知识多少给人分等级，也不是轻看初信者。悔改与信心的根基始终重要。问题在于，人反复听见这些基础教导，却不用它们分辨善恶并采取行动。能吃干粮，不是能讲许多复杂教义，而是能把神的话用在不同的生活处境中，分辨神的旨意。这样的分辨力，是在一次次顺服中逐渐成长的。\\n\\n当时的听众需要分辨：建立看得见的圣殿和强大的国家，真是通往救恩的道路吗？还是应当跟随耶稣，即使在苦难中，也顺服神的旨意？一件事无论显得多么虔诚、得到多少支持，若以牺牲生命为代价，为仇恨和暴力辩护，就不能轻易说它出于神。愿意聆听的人，不只跟随熟悉的口号，而会用耶稣的话察看现实。作者的责备并非给听众贴上无能的标签，而是包含着盼望：只要实际运用已经学过的话，他们仍能继续成长。\\n\\n今天的信息里，有一位牧者迫切盼望信徒成长的心。前几天，我看了统计，我们教会共有51个孩子。父母养育孩子虽然辛苦，却因期待他们健康成长而重新得力。如果期待中的成长迟迟不见，难处又接连而来，父母会多么牵挂！《希伯来书》作者的心也是如此。我有时也有这样的感受。我盼望你们更深认识圣经，让神的话改变你们看世界、看人生的眼光和价值观，使你们有力量走耶稣所指明的道路。当我觉得这份心意和付出没有被理解、接纳时，也会难过。我切切盼望的，不是你们一直单向地向我学习，而是我们彼此学习、一同成长。今天，也盼望你们体谅我的这份心。我相信，一同思想牧者盼望信徒成长的心意，也能成为我们寻求神旨意的时刻。","prayer":"天父，求您使这些弟兄姊妹在您的话语中成长。愿他们所学的改变思想和价值观，成为有力量跟随耶稣的生活。求您也保守我，在等候信徒成长时不失去耐心和爱；心里难过时，懂得向您寻求智慧。愿我们体谅彼此的心，一同学习、成长。也求您坚固养育孩子的父母，使我们的群体与下一代一同在信心中成长。阿们。"},"handbook":{"today_focus":"属灵成熟不是知道更多复杂术语，而是把已经听见的道付诸行动，逐渐长出分辨善恶的能力。即使耳朵曾经迟钝，也可以借着提问、承认错误和实际顺服重新学习聆听。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"作者为什么暂时停止讲解麦基洗德？"},{"question":"\\"奶\\"和\\"干粮\\"的比喻强调了怎样的操练？"}],"meditations":[{"question":"我在哪些领域听了很多，却很少付诸行动？","hint":""},{"question":"面对眼前需要作出的决定，我若依据耶稣关于生命、爱和公义的教导来分辨，会有怎样的判断？","hint":""},{"question":"我是否因为害怕显得无知，而不愿提问或承认判断错误？","hint":""}],"practices":["选一个现实决定，列出事实、受影响的人和耶稣教导的准则。","对不明白的地方提出一个诚实问题。"],"prayer":"求主恢复我愿意聆听和学习的心。\\n求主使知识在顺服中成为分辨力。\\n求主赐我承认错误并重新学习的谦卑。"}},{"day":12,"chapter":6,"title":"在严厉的警告中仍盼望更美的事","key_verses":"来 6:4-12","story_section":"大祭司","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第6章用十分严厉的话，描述那些曾蒙光照、尝过属天恩典，后来却离弃的人。我们应当把这警告放在群体实际面临的忠诚抉择中理解。他们知道借着耶稣来到神面前的道路，也在群体中经历过恩典；然而，在压力和疲惫中，他们可能放弃这条路，再次把眼前的圣殿和祭司制度当作救恩的中心。作者没有淡化这种选择的严重性。\\n\\n6章4--6节关于离弃以后不能重新悔改的警告极为严肃，不能轻轻带过。但我们也不应立刻把这段描述，套在每一个跌倒后懊悔、渴望回转的人身上。作者用最强烈的语言，让人感受到：明明认识耶稣的道路，却故意弃绝，并在人前再次羞辱他，是何等严重的选择。他将此比作再次把神的儿子钉十字架，但并不是说十字架事件真的重演。这是强烈的讲道表达，要显明在人前拒绝耶稣、转向别的救恩道路，是多么严重的背叛。\\n\\n接下来关于土地的比喻，说明同样领受雨水，也可能结出不同的果子。过去经历恩典、长期属于教会群体，并不会自动保证将来的救恩。所领受的话，应当结出爱的服事、长久承担责任，以及顺服耶稣旨意的果子。这警告的重点在于，我们不能把曾经尝过神恩典的记忆，与今天的生活完全分开。\\n\\n不过，作者随即亲切地称呼他们，并表达对他们的信任。他相信他们会结出更好的果子，走向最终的救恩（6:9），并没有断定眼前的读者已经被神弃绝。相反，他记得他们服事圣徒时显出的爱心和辛劳。严厉警告之后紧接着安慰，并非要用恐惧把人赶出群体，而是要唤醒松懈的人，使他们重新持守盼望，顺服到底。警告与鼓励并不矛盾，而是出于同一个牧养目的。因此，我们不必用这段话逼着自己无休止地怀疑是否得救，而应把它当作一面镜子，诚实省察自己现在正朝哪个方向前行。\\n\\n今天的经文也说明救恩与行为的关系。读圣经时，我们应当让自己的思想被校正。《希伯来书》不断把救恩、安息与我们的生活紧密相连：向不悔改的人警告神的管教，也鼓励信徒，公义的神不会忘记他们的辛劳，以及为他名所显出的爱。现在，你们当中可能有不少人正在家乡。真正回去以后，故乡未必像思念中那样令人自在。在这样的环境里按神的旨意生活，心情可能很复杂，甚至有时想暂时放下基督徒的责任。亲爱的弟兄姊妹，神知道你们的辛劳。公义的神不会忘记你们为他的名所付出的爱。盼望你们记得这话，今天也重新得力。","prayer":"天父，感谢您不忘记信徒的辛劳和爱。求您体谅那些在故乡和家人中难以按信仰生活的弟兄姊妹。当基督徒的责任让他们觉得沉重时，愿他们因相信您记念他们的付出而得力。求您使他们在熟悉的关系中仍继续爱与顺服，也赐他们勇气离开错误的道路。愿我体谅他们的处境，及时鼓励他们，让我们都持守盼望到底。阿们。"},"handbook":{"today_focus":"这段经文严肃警告人不要故意离弃耶稣的道路，却也记念读者过去爱心的服事，并确信他们有\\"更美的事\\"。警告不是把愿意回转的人赶出去，而是唤醒疲惫的人继续结出属于救恩的果子。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"田地的比喻怎样说明同样领受恩典却结出不同果子？"},{"question":"作者在严厉警告后，为什么立刻称读者为\\"亲爱的\\"并记念他们的劳苦？"}],"meditations":[{"question":"我是否因这段警告不断怀疑自己，却没有认真察看自己正在朝什么方向前行？","hint":""},{"question":"我过去为圣徒付出的哪一份爱和劳苦，可以今天重新记起？","hint":""},{"question":"哪一种看起来更安全、更有力量的选择，可能正在使我离开耶稣的道路？","hint":""}],"practices":["为过去一项真实的爱心服事感谢神。","处理一个拖延的责任，或重新联系一位久未照顾的人。"],"prayer":"求主使严厉的警告唤醒我，而不是把我推向绝望。\\n感谢神记念爱心所作的工。\\n求主使我不懒惰，继续持守盼望和顺服。"}},{"day":13,"chapter":6,"title":"如同灵魂之锚的盼望","key_verses":"来 6:13-20","story_section":"大祭司","letter":{"body":"亲爱的弟兄姊妹：\\n\\n神向亚伯拉罕应许，并指着自己起誓。在古代社会，起誓是保证言语可信、终止争论的庄严举动。神本来就不可能说谎，但《希伯来书》说，他体谅那些必须长久等候应许之人的软弱，因此又加上誓言。亚伯拉罕也没有立刻得到所应许的，而是经历了漫长的等待。作者借着这段故事，帮助疲惫的群体重新信靠神的品格和应许。\\n\\n作者把这盼望比作灵魂的锚。锚不能使海浪消失，也不能让船毫不摇晃，却能在风浪中稳住船，使它不至漂走，或撞上危险的地方。基督徒的盼望，也不只是乐观地期待问题马上解决，或维持明亮、积极的情绪，而是把心和生活牢牢系在这个事实上：神信守他的约，耶稣已经先进入神面前，为我们开通道路。有盼望的人也会摇晃，却不至失去方向。\\n\\n经文把这盼望描绘为进入幔子里面的锚（6:19）。作者把海上的锚与圣所的幔子两幅不同的图画连在一起，说明群体的盼望牢牢系于那看不见、却与他们同在的神。我们不必等到圣殿幔子再次立起、祭礼完全恢复，才可以亲近神。耶稣作为先锋已经进入，因此，无论眼前处境如何，听众的盼望已经通达神面前。耶稣按麦基洗德的体系成为大祭司，也强调这条路不只依赖利未制度。\\n\\n这样的盼望，不会使人为了等候未来而放下今天的责任。亚伯拉罕即使久久看不到应许实现，仍忍耐前行。《希伯来书》的听众也不能被一种期待支配，以为只要圣殿和国家赶快恢复，一切就会好起来。盼望不是否认内心的不安，而是在结果迟迟未见时，不冲动地走上错误道路，仍继续顺服神的话。教会不应只责怪等候疲惫的人没有耐心，而应陪他们一同抓住锚绳。\\n\\n即使走在基督的道路上，我们仍会摇晃，因为我们还在经过旷野。等候工作、渴望孩子、盼望结婚的人，都处在等待的旷野中。即使相信神会赐福给跟随基督的人，心里也可能动摇、疑惑。我也相信神会赐福给忠心服事教会的我，但有时仍会生出怀疑。这时，我们需要再次抓住盼望的锚绳。我也愿倚靠这盼望，更认真地做好现在能做的事。我恳切祷告，愿你们与我一同持守神的应许，忠心守住今天所在的位置。","prayer":"天父，我把那些在等待中动摇的弟兄姊妹交托给您。求您安慰渴望工作、孩子和婚姻，却等得疲惫的心。即使疑惑出现，也愿他们倚靠您的信实，再次抓住盼望的锚绳。求您使我怀着同样的盼望，与信徒一同等候；让我们不因彼此的摇晃而责怪对方，而是在身旁给予力量。愿我们都忠心做好今天能做的事，跟随您的引导。阿们。"},"handbook":{"today_focus":"盼望不是没有波动的情绪，也不是保证问题迅速解决。它像锚一样，把摇晃的生命连在神可信的应许和耶稣已经开启的道路上，使我们在等待中不至于完全漂流。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"神为什么在应许之外又加上誓言？"},{"question":"\\"灵魂的锚\\"进入幔内，这个图像说明盼望与什么相连？"}],"meditations":[{"question":"我正在等待什么：工作、治疗、关系、家庭改变，还是别的？","hint":""},{"question":"焦虑是否使我不断查信息、催促结果，或作出冲动决定？","hint":""},{"question":"在尚未得到最终答案时，今天有哪些责任是我仍可以安心履行的？","hint":""}],"practices":["减少一次无助的重复确认，把这段时间用于一件当下能做的责任。","不要催促正在等待的人；提供一项具体而实际的帮助。"],"prayer":"感谢神的应许和性情可靠。\\n求主在摇动中使我的心重新系在他身上。\\n求主赐我等待的忍耐，也赐我今天忠心生活的力量。"}},{"day":14,"chapter":7,"title":"麦基洗德的祭司职分带来更美的盼望","key_verses":"来 7:1-19","story_section":"大祭司","letter":{"body":"亲爱的弟兄姊妹：\\n\\n麦基洗德是《创世记》第14章短暂提到的撒冷王，也是至高神的祭司。他为亚伯拉罕祝福，接受亚伯拉罕献上的十分之一。然而，《创世记》没有记载他的父母、家谱或死亡。《希伯来书》借着这叙述特点，说明耶稣的祭司职分。7章3节提到父母、家谱和生死的记载，重点在于圣经怎样呈现这个人物，并不是作生物学说明，或断定麦基洗德不是人。作者借着没有交代家谱和死亡的叙述，强调他的祭司职分在利未家谱之外。\\n\\n利未祭司职分曾在以色列的敬拜和群体秩序中发挥重要作用。然而，当人再次把圣殿和祭司制度的恢复，视为亲近神的终极道路时，作者引用麦基洗德和《诗篇》第110篇，挑战只有利未血统才能保证祭司资格的观念。耶稣出自犹大支派，不属于摩西律法规定的祭司家族。《希伯来书》说，他成为祭司，不是依据有关血统的条例，而是依据胜过死亡、不会被死亡消灭的生命之大能（7:16）。\\n\\n这番比较并非中立介绍各种制度的课堂，而是劝听众重新决定向谁忠心。更美、更改、废除等强烈措辞，要使人不被眼前圣殿和家谱的权威吸引，而是持守借着耶稣开启的更美盼望。不能把这些话扩大成旧约和整个犹太教毫无价值的宣告。作者把同一本圣经中短暂出现的麦基洗德放在重要位置，让我们看见，神也能在熟悉的制度之外开出新的道路。\\n\\n借着这更美的盼望，我们得以亲近神（7:19）。传统和制度若能引导人亲近神、亲近邻舍，就十分宝贵。但若家世、职分、学历和长期惯例只是保护少数人的权威，阻碍弱小者参与，就需要在耶稣的道路前重新省察。当时的听众不能只等候圣殿和国家复兴，而应选择耶稣已经开启的道路。关于麦基洗德的论述，打破了神只借着既有血统和核心制度作工的想法，也引导群体更开阔地看待圣经和人。\\n\\n我们教会理解圣经时，重视历史背景和经文的整体脉络。对过去以教义为中心学习圣经的人来说，这种方式可能陌生。若把教义当作已经确定、无需再问的真理，就可能难以认真考虑其他解释。尤其是16至17世纪神学家系统整理的基督教新教教义，其中包含着当时的问题和时代背景。因此，教义本身也需要在圣经的历史和上下文中接受检验。考察历史背景和经文脉络，也是许多神学院采用的研究方式。我们不只希望理解经文，还像《希伯来书》所强调的那样，重视实际跟随耶稣的生活。亲爱的弟兄姊妹，让我们珍惜群体的方向和追求，一同学习、实践神的话，愿耶稣的教导实现在我们的生活中。","prayer":"天父，感谢您使我们的群体能够一同学习、实践您的话。求您赐我们智慧，认真考察圣经的历史背景和上下文，也愿意用您的话检验熟悉的观念。愿面对陌生学习方式的弟兄姊妹能够安心提问，也愿我带着耐心和爱，与大家一同学习。求您使我们珍惜共同追求的方向，更深认识您的话，并把所领悟的活出来，继续跟随耶稣。阿们。"},"handbook":{"today_focus":"神的工作不被熟悉的血统、职位和制度限制。传统若帮助人亲近神、爱人，就值得珍惜；若只保护少数人的权力、阻挡别人的参与，就需要在耶稣的道路中重新审视。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"作者怎样利用创世记对麦基洗德记载的特点展开论证？"},{"question":"\\"更美的指望\\"最终使人能够做什么？"}],"meditations":[{"question":"我把哪一种制度或做法看作绝对不能改变？","hint":""},{"question":"这项传统正在帮助人亲近神，还是主要保护熟悉者的利益和地位？","hint":""},{"question":"我是否因别人没有职位、学历或经验，就轻看他的意见？","hint":""}],"practices":["认真听一位职位较低或经验较少之人的意见。"],"prayer":"感谢神能在熟悉制度之外开启道路。\\n求主给我珍惜传统又不把传统绝对化的智慧。\\n求主使我们的群体给更多人亲近神、参与服事的空间。"}},{"day":15,"chapter":7,"title":"长远活着为我们代求的主","key_verses":"来 7:20-28","story_section":"大祭司","letter":{"body":"亲爱的弟兄姊妹：\\n\\n旧约的祭司代表百姓站在神面前，但他们都是人，无法逃避死亡，因此不断需要继任者。《希伯来书》说，耶稣是神以誓言所立、永远的大祭司。他胜过死亡，长远活着，所以他的职分不会中断。作者引用《诗篇》第110篇的誓言，是要说明耶稣的祭司职分不只取决于人的制度和任命，而是立在神的应许之上。因此，他能拯救那些借着他来到神面前的人，直到最后。\\n\\n耶稣长远活着、为人代求的话（7:25），显明神主动赐下并持续施予的怜悯。神先立耶稣为大祭司，又借着他的服事，坚固来到神面前之人的信心。旧约大祭司的礼服上有刻着以色列众子名字的宝石，表明他承担着在神面前记念百姓的职分。同样，耶稣不断为那些借着他亲近神的人代求。这份看顾不会因一场礼仪结束而停止，也不受死亡限制。\\n\\n他能拯救到底，不只是说他能把人从暂时的危机中救出一次，而是说他能引导亲近神的人，最终进入生命。耶稣的代求，也不保证我们可以任意生活、不负责任。它帮助我们在失败和试探中回到神面前，承认错误，再次走顺服的路。耶稣知道我们的软弱，却不会任凭我们停留在罪和不义中。他不断坚固我们，使我们继续过亲近神的生活。\\n\\n这番对照，反驳了只有圣殿和祭司组织恢复，教会才能安全的想法。作者引导我们信靠耶稣那看不见、却永不中断的祭司职分。人的领袖会更换，制度会动摇，再优秀的人也逃不过死亡和自身的限制。因此，群体的救恩与未来，不能寄托在某个领袖永不改变，或某种制度长期维持的期待上。听众应当信靠活着的耶稣在神面前持续所做的工作，顺服他的话。耶稣的代求，是大祭司给予的看顾：他不忘记我们的名字，常把我们放在神面前，在引导我们进入应许的生命之前，不会半途放弃。\\n\\n我们忠心遵行耶稣的话，朝着安息前行，却仍要经过不同的旷野，也会面对自己的软弱。今天的经文教导我们，永远的大祭司耶稣会带领我们亲近神，进入应许的生命。亲爱的弟兄姊妹，即使仍有不足，也请记得，我们有为我们代求的耶稣。今天，让我们忠心做好能做的事，仰望那位垂听耶稣代求的神。盼望这份确信，成为你们再次前行的力量。","prayer":"天父，感谢您借着常为我们代求的耶稣看顾我们。求您坚固那些在旷野般的日常生活中面对自身软弱的弟兄姊妹。当我们因不足而灰心时，求您使我们记得，那位带领我们亲近您的耶稣仍在为我们代求。愿我们仰望您的帮助，忠心做好今天能做的事；也愿我与他们同行，常常鼓励他们。求您使我们都走完顺服的道路，进入您应许的生命与安息。阿们。"},"handbook":{"today_focus":"人的领袖会改变，制度也会动摇；耶稣的大祭司职分却不因死亡中断。他长远活着为来到神面前的人代求，扶持他们在失败和试探中回转，并走向最后的生命。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"耶稣的祭司职分与会死亡、更替的祭司有什么不同？"},{"question":"\\"拯救到底\\"与耶稣长远代求之间有什么关系？"}],"meditations":[{"question":"我是否把群体的安全过度寄托在某位领袖或某种制度上？","hint":""},{"question":"当祷告说不清、心里混乱时，耶稣的代求给我怎样的安慰？","hint":""},{"question":"我是否只对有需要的人说\\"为你祷告\\"，却没有确认他的实际需要？","hint":""}],"practices":["在表达不完整的情况下，也诚实向神说出惧怕和错误。","为一个人祷告以后，再确认一项可以实行的照顾。"],"prayer":"感谢耶稣长远活着为我们代求。\\n求主使我不把盼望系在会改变的人和制度上。\\n求主借着他的中保工作，使我重新有力量顺服。"}},{"day":16,"chapter":8,"title":"刻在心里的更美之约","key_verses":"来 8:1-13","story_section":"新约","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第8章称耶稣为更美之约的中保，并长篇引用《耶利米书》第31章有关新约的应许。耶利米所传的应许，并不是说神要抛弃以色列，另选一群毫不相关的人，而是说，他要与经历巴比伦危机、曾经背约的以色列家和犹大家重新建立关系，把律法写在他们心里。这是恢复关系的应许。《希伯来书》的作者把这古老的应许再次传给眼前的群体，询问他们：神子民真正的复兴，究竟是什么？\\n\\n把律法写在心里，并不是说命令和责任从此消失，人人可以随心所欲，而是说，神的律法不再只停留在外在条文或口头背诵中，而要深入思想、愿望、选择和习惯，引导实际生活。认识神，也不只在于知道许多知识，而是在与神的关系中，爱他的旨意，并照着去行。因此，新约的核心不在于废除一切制度，而在于神的子民被改变，甘心而持久地顺服他的旨意。\\n\\n神应许不再记念他们的罪（8:12），并不表示人可以故意继续行不义而不受过问。赦免是神修复破裂的关系，使人能够再次顺服的行动。在《希伯来书》中，赦罪与把律法写在心里，属于同一个应许。承认错误、愿意回转的人，不必永远被过去的罪困住，也不必无休止地被排斥，而能开始重新服事神和邻舍的生活。但若一面谈赦免，一面漠视受害者、固执地不肯顺服，就偏离了新约的目的。\\n\\n当时，圣殿和以色列国家看得见的恢复，可能被视为神子民重新建立的最明显标志。然而，作者说明，群体的更新并不只靠更大、更强的建筑和制度。当百姓认识神，他的旨意刻在他们心里、活在生活中，约的真正恢复才发生。8章13节强烈地说先前的约渐渐陈旧，也不是宣告神抛弃所有犹太人，而是借着讲道中的对照，提醒人不要把外在秩序的恢复，误当作救恩的完成。\\n\\n今天，作者换一个角度，再次说明贯穿《希伯来书》的主题：耶稣所指明的道路，胜过圣殿制度和祭司所主导的道路。我们最近正在学习约，不久也会学习新约。新约以耶稣所显明的神的旨意，以及人对这旨意的顺服为基础。人若顺服耶稣所传明的神的旨意，神就与他们同在，赐福给他们。其实，赐福与救恩是相近的概念。今天，让我们思想耶稣的一项教导。[《马太福音》7章12节](https://www.biblegateway.com/passage/?search=Matthew+7%3A12&version=CNVS)说：\\"所以，你们愿意人怎样待你们，你们也要怎样待人，这是律法和先知的总纲。\\"（《新译本》）让我们省察自己，使自己的心与耶稣的教导一致。","prayer":"天父，感谢您以怜悯接纳愿意回转的人，使我们能够重新亲近您。求您把您的旨意深深写在这些弟兄姊妹心里，引导他们每天的言语和选择。愿他们在关系受伤、难以相处时，仍能学习耶稣，体谅别人，也勇于改正自己的过失。求您也帮助我，把所教导的话活出来，耐心陪伴大家，让我们在彼此相待中显出您所赐的新生命。阿们。"},"handbook":{"today_focus":"新约不是取消责任，而是神使他的旨意进入人的思想、欲望、习惯和选择。赦免也不是让人继续伤害而不负责任，而是恢复关系，使回转的人能够开始新的顺服生活。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"耶利米书的新约应许是向谁说的？"},{"question":"\\"律法写在心上\\"和\\"不再记念罪恶\\"在同一个应许中怎样相连？"}],"meditations":[{"question":"神的旨意需要在我的说话、金钱、时间或家庭关系中怎样成为习惯？","hint":""},{"question":"我是否用\\"已经被赦免\\"逃避对受伤者的责任？","hint":""},{"question":"我心里已经长出哪些诚实、怜悯或守约的习惯，可以为此感谢神？","hint":""}],"practices":["选择一个生活领域，定下一项小而持续的改变。","若曾造成伤害，思考应有的道歉、归还、补偿或界限调整。"],"prayer":"感谢神愿意重新建立破裂的关系。\\n求主把他的旨意写进我的选择和习惯。\\n求主赐我真实悔改、承担责任和重新开始的力量。"}},{"day":17,"chapter":9,"title":"地上圣所所显明的道路与局限","key_verses":"来 9:1-10","story_section":"新约","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第9章回顾会幕的结构和敬拜条例。灯台、摆放陈设饼的桌子、约柜，以及隔开圣所与至圣所的幔子，都与以色列认识神的圣洁、学习敬拜有关。祭司常常进入外面的圣所服事，里面的至圣所却只有大祭司能在每年赎罪日独自带血进入。大祭司自己也有软弱和罪，因此也必须为自己的罪献祭。作者借着听众熟悉的敬拜场所，说明亲近神的道路，同时显明当时敬拜制度的局限。\\n\\n第一层帐幕可以天天进入，第二层帐幕却几乎无人能进。这对比并不是在作神离人遥远的哲学论述，而是把当时敬拜制度中关于谁能进入、能到哪里为止的严格界限，用作讲道中的象征。9章8节把前面的帐幕仍然存在，与通往至圣所的道路尚未显明联系起来。这不是说会幕毫无意义，而是说，它的结构本身显明了神的圣洁、人的罪，以及两者之间仍存在的距离和限制。\\n\\n关于饮食、洗濯和洁净的条例，帮助以色列在身体和群体生活中建立界限，维系自己的身份。但作者说，这些礼仪无法使敬拜者的良心得到完全的更新。遵守洁净程序，并不等于从心里顺服神。这也不是说身体和礼仪没有价值，而是说，若身体参与的敬拜没有带来按真理和公义生活的改变，其局限就显露出来。\\n\\n犹太人之所以被重建圣殿的运动吸引，是盼望借着献祭恢复与神的关系。然而，在这样的圣殿制度下所献的祭，不能使人产生根本的改变。耶稣虽然曾进入圣殿，却没有把圣殿制度当作救恩的途径来宣讲。他在[《约翰福音》6章63节](https://www.biblegateway.com/passage/?search=John+6%3A63&version=CNVS)说：\\"我对你们所说的话是灵、是生命。\\"（《新译本》）在《约翰福音》中，生命有救恩的含义。\\n\\n许多人参加默想和主日崇拜，这与犹太人参与圣殿礼仪有相似之处。这样的参与很有意义，但参与本身并不能拯救我们。走进耶稣所教导的道路，我们才得着生命。今天，我想以耶稣的话结束这封信。《马可福音》1章14--15节记载：\\"耶稣来到加利利，宣讲神的福音，说：'时候到了，神的国近了，你们应当悔改，相信福音。'\\"（《新译本》，节录）这段话直接把神的福音与悔改相连。《路加福音》24章47节也说：\\"人要奉他的名，传讲悔改与赦罪的道，从耶路撒冷起，直传到万国。\\"（《新译本》）这话清楚指出罪得赦免的条件和途径，强调人需要悔改，而不只是向神献祭。今天，让我们省察自己，从错误的道路回转，走进耶稣所指明的道路。","prayer":"天父，感谢您使这些弟兄姊妹有机会一同敬拜、聆听您的话。求您帮助我们诚实省察自己，看见生活中需要回转的地方，并赐下改变的力量。愿那些因羞愧而不敢面对自己的人，在您的怜悯中愿意重新开始。求您也赐我一颗肯聆听、肯悔改的心，与大家一同走耶稣所教导的道路，使我们的敬拜在日常生活中结出良善的果子。阿们。"},"handbook":{"today_focus":"地上的圣所和礼仪曾教导神的圣洁，也显出人亲近神时仍有的距离和限制。外在礼仪本身不能使良心成熟；敬拜必须进入诚实、公义和对邻舍的责任。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"第一层帐幕和至圣所的进入方式有什么不同？"},{"question":"作者怎样说明礼仪在当时的意义和局限？"}],"meditations":[{"question":"我是否把参加聚会、完成程序或遵守形式，当成生命已经改变的证明？","hint":""},{"question":"最近一次敬拜带给我什么安慰、提醒或责任？","hint":""},{"question":"我们的群体是否给软弱者一个安全说话、开始恢复的位置？","hint":""}],"practices":["把敬拜中领受的一点亮光，转化为一项道歉、分享或保护人的行动。","感谢神赐下共同敬拜的地方，同时检视形式是否遮住了真实需要。"],"prayer":"感谢神借着敬拜教导我们他的圣洁。\\n求主使外在敬拜进入内心和生活。\\n求主使我们的群体成为人能安全亲近神、开始恢复的地方。"}},{"day":18,"chapter":9,"title":"洁净良心的基督之血","key_verses":"来 9:11-28","story_section":"新约","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》说，耶稣进入的不是人手所造的圣所，而是更大、更完全的帐幕。他没有带着山羊和牛犊的血进去，而是献上自己的生命。在古代献祭中，血不只是物质，也表明生命被献给神，罪和破裂的关系在其中得到处理。作者借着耶稣忠信地献上自己，重新解释献祭的意义。耶稣不是以别的生命代替自己生命的祭司，而是顺服神到底，献上自己身体和生命的大祭司。\\n\\n基督的血洁净良心，并不是说过去的记忆和创伤会像魔术一样消失，或人从此没有任何责任。这里的良心，不只涉及内疚的感觉，也关乎人在神面前反省自己的生活，并能否再次服事他。一个曾因掩盖谎言、逃避责任而无法好好服事神和邻舍的人，如今借着基督献上自己，能够诚实面对罪，领受赦免、回转，再次服事神。良心得洁净的果子，会在这样的生活改变中显明。脱离导致死亡的行为（9:14），不只是心里轻松一点，而是生命的方向确实改变。\\n\\n旧约的赎愆祭条例也规定，抢夺或欺骗别人的人，应当先归还原物，再加上五分之一，然后献上赎愆祭（利未记6:1--7）。向神求赦免与对受害者负责，从一开始就没有分开。因此，若一面谈耶稣的血，一面继续掩盖谎言、不归还所夺之物，还要求受伤的人赶快原谅，就离清洁的良心很远。那位献上自己的基督，呼召我们面对真相、承担责任，重新服事神和邻舍。\\n\\n一次献上自己，与不断重复的献祭和圣殿秩序形成强烈对照。这不是简单宣告所有时代的犹太教都已失效，而是要反驳一种期待：必须等到圣殿和献祭完全恢复，救恩的道路才会开启。作者宣告，耶稣的顺服和自我奉献，无须再加上其他祭物，群体应当向他忠心。同一段经文也说，人死后要面对审判，耶稣将再次向等候他的人显现。作者把今天的回转与将来要承担的责任，一同摆在我们面前。\\n\\n有些人依据今天的经文，相信耶稣担当了我们的罪，所以我们的罪已经得赦免，并由此主张，人不是凭行为得救，而是完全凭恩典得救。他们认为，人不完美，神却绝对良善，所以这问题只有借着耶稣才能解决。这是一种人的解释，并不是圣经本身这样说。我们正在持续学习《希伯来书》。圣经并不要求我们过毫无缺欠的生活，因为我们不可能完美；但我们相信，若按耶稣所显明的神的旨意生活，神就赐给我们生命。今天若发现自己的不足，不必试图一下子全部改变，可以先在一件做得到的事上回转。盼望你们这样调整人生的方向，经历耶稣所赐的生命。","prayer":"天父，感谢您借着耶稣献上自己，为我们开启重新服事您的道路。我把那些被内疚和过去的伤害困住的弟兄姊妹交托给您。求您安慰受伤的人，赐他们恢复的空间；也赐犯错的人勇气，诚实承认过失，承担应负的责任。愿我们今天就在一件做得到的事上回转。求您也使我体谅每个人的难处，陪伴他们重新得力，以清洁的良心服事您和邻舍。阿们。"},"handbook":{"today_focus":"基督的血洁净良心，不是抹去记忆和责任，而是使人不再靠隐藏和逃避生活，能够说出真相、回转、承担应有责任，再次事奉永生神。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"耶稣进入圣所所带的\\"血\\"与旧约祭物有什么不同？"},{"question":"经文怎样把基督一次献上、审判和将来的显现连在一起？"}],"meditations":[{"question":"我是否把罪疚当作悔改，却仍没有面对真相和造成的损害？","hint":""},{"question":"有没有需要归还、补偿、说明或停止的行为？","hint":""},{"question":"什么使我相信：即使承认错误，我仍可以重新事奉神？","hint":""}],"practices":["把一件错误说清楚，不用模糊的词减轻责任。","在安全和合宜的前提下，开始一项道歉、归还或补偿。"],"prayer":"感谢基督的自我献上为回转打开道路。\\n求主洁净我的良心，使我不再隐藏和逃避。\\n求主赐我承担后果、修复关系并重新服事的勇气。"}},{"day":19,"chapter":10,"title":"一次献上所开启的新路","key_verses":"来 10:1-18","story_section":"新约","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第10章把律法中的祭物看作将来美事的影子。接着，作者引用《诗篇》第40篇，以甘愿前来遵行神旨意的祷告，说明耶稣献上自己的心意。这段经文不只抽象讨论祭物怎样产生功效，其中心是：神所要的，不是不断献祭这个行为本身，而是顺服他旨意的生活；耶稣则用自己的身体，把这顺服实行到底。作者把诗篇中的祷告与耶稣的一生放在一起阅读，将献祭的意义集中在顺服上。\\n\\n作者鲜明地对照两个场景：祭司天天站着，献上相同的祭；耶稣一次献上自己以后，却坐下了。一次献上与坐下，都强调耶稣的使命已经完成。当时，有人期待圣殿和祭司制度再次强盛，才能来到神面前。但作者宣告，借着耶稣的顺服，新路已经开启。听众不应把终极盼望寄托在不断重复的制度上，而应忠于那位以身体遵行神旨意的耶稣。\\n\\n10章14节说，基督借着一次献祭，使那些成圣的人永远完全。但这并不表示以后怎样生活都无所谓，也不再需要改变。经文随即引用新约的应许，说神要把律法写在人心里。耶稣的死，不是让信徒继续留在过去的罪中，或给犯罪的人一张免罪凭证，而是使他们顺服律法，也就是神的旨意。这段话并非只是在说，耶稣担当了我的罪，所以我已经从罪中解脱。耶稣把自己的一生献上，即使面对死亡的恐惧，也仍顺服神的旨意，向人传明这旨意；正是借着这样的生命，人被引导去走他的道路。\\n\\n作者使用强烈的重复和对比，并不是简单说明旧约所有祭物从一开始就没有价值。正如《使徒行传》所记载的，早期犹太信徒并非全都立刻停止参与圣殿礼仪。在圣殿和国家复兴的期待格外强烈时，《希伯来书》询问这个群体：你们最终把盼望和忠诚放在哪里？献祭和敬拜不能代替遵行神旨意的生活。同样，一个宣讲耶稣献上自己的群体，也应当在现实中实践公义与爱。\\n\\n耶稣指明的道路，是跟随他顺服的路，而不是逃避责任的路。如果有一件事让你反复后悔，却一直没有改正，就从道歉、赔偿或改变习惯中，选定一个具体行动开始。愿亲近神的喜乐，不断结出诚实与爱的顺服之果。","prayer":"天父，感谢您借着耶稣顺服到底的一生，使我们看见亲近您的道路。求您扶持那些反复后悔、却不知怎样改变的弟兄姊妹，使他们能从一个具体行动开始，诚实道歉，补偿亏欠，逐渐改变伤害人的习惯。愿他们在回转中领受您的怜悯，重新得着亲近您的喜乐。求您也提醒我，以自己的生活回应所传讲的话，与大家一同学习顺服。阿们。"},"handbook":{"today_focus":"耶稣一次献上自己，强调他在顺服中完成了神交托的使命，也为群体开启了亲近神的新路。这个宣告不是鼓励人停留在罪中，而是使人带着被洁净的良心，继续被神的旨意塑造。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"律法中的祭为什么被说成每年使人想起罪？"},{"question":"经文怎样把耶稣的身体、神的旨意和一次献上联系起来？"}],"meditations":[{"question":"我是否把\\"已经完全\\"理解成生活不再需要改变？","hint":""},{"question":"耶稣\\"照神的旨意而来\\"的顺服，今天怎样成为我的道路？","hint":""},{"question":"哪些重复的罪疚使我只盯着过去，无法继续行善？","hint":""}],"practices":["放下无休止的自我惩罚，同时认真停止一项明知有害的行为。","记住一项神已经为你打开的亲近之路，并以感恩回应。"],"prayer":"感谢耶稣以顺服开启亲近神的道路。\\n求主使我不轻看罪，也不被过去的罪疚困住。\\n求主继续把他的旨意放在我心里，使我能忠心遵行。"}},{"day":20,"chapter":10,"title":"亲近神 持守盼望 彼此鼓励","key_verses":"来 10:19-25","story_section":"新约","letter":{"body":"亲爱的弟兄姊妹：\\n\\n说明耶稣献上自己、开通来到神面前的道路之后，《希伯来书》向教会提出三项劝勉：以真诚的信心亲近神，持守所宣认的盼望，并彼此关顾，使爱心落实为善行。前面对圣所和献祭的详细说明，并不是为增加一套新理论，而是要改变群体的生活。通往神的道路，不只在人心里，也包含着一同承担彼此生活的责任。\\n\\n亲近神，并不表示人必须先达到毫无恐惧和内疚的完美状态，才有资格站在他面前，而是说，我们不再隐藏错误和软弱，相信耶稣已经开通道路，在神面前寻求怜悯，以及顺服的力量。持守所宣认的盼望，也不只是处境看好时保持积极心态，而是因为应许的神信实，即使承受压力和损失，仍不放弃耶稣所指明的生命与爱之路。信心包含口里的宣认，也包含持续的行动。\\n\\n彼此关顾的劝勉（10:24），不是叫我们监视、评判别人的出席和行为是否合格，而是要细心了解对方的处境，提供实际帮助，使疲惫的人重新有力量去爱、去行善。竞争、内疚和公开羞辱，不能催生真正的爱。我们需要留意，谁因照顾他人的责任而耗尽心力，谁因经济重担而躲避人群，谁因冲突而不愿聚会。当大家愿意一同分担责任，群体才能真正彼此鼓励，继续行善。\\n\\n10章25节不要放弃聚集的劝勉，也不是无视每个人的处境，一律强迫出席。当时信徒承受压力，若陷入孤立，就容易离开耶稣的道路，回到看得见、似乎更安全的秩序中。因此，作者劝他们尽力保持联系。对于因疾病或危险不能参与的人，我们应当先关心健康和安全，不急着追问出席，也可以安排线上聚会、探访等合适方式。聚会的目的，是帮助彼此顺服到底，而不只是凑齐人数。\\n\\n读到这里，我为我们的弟兄姊妹感谢神。教会里许多人虽然走过人生不同的旷野，仍坚定前行，用心关顾彼此，互相鼓励行善。你们积极参与主日聚会和周间小组，继续认识神。不要在基督里只顾责备自己，你们也可以为正在行走的这条路感到欣慰。若意识到还有不足，就在已经做的事情上，再添一项可以实践的行动。愿神赐福给忠心走主道路的你们。","prayer":"天父，感谢您使这些弟兄姊妹在各自的难处中，仍愿意彼此关顾、互相鼓励。求您坚固他们的盼望，也让他们为已经走过的信心道路感到欣慰。请看顾因疾病、重担或关系受伤而渐渐孤单的人，使他们得到合适的陪伴和实际帮助。求您也赐我细心，先听懂他们的处境，再与大家一同分担。愿我们的相聚使疲惫的人重新有力量去爱、去行善。阿们。"},"handbook":{"today_focus":"耶稣所开的路把个人亲近神与群体生活连在一起。我们坦然来到神面前、持守盼望，也要彼此留意，实际帮助疲惫的人重新活出爱心和善行。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"这一段连续出现了哪三个\\"要\\"或\\"应当\\"？"},{"question":"\\"彼此相顾\\"与\\"不可停止聚会\\"的目的是什么？"}],"meditations":[{"question":"我是否认为亲近神只是个人内心的事，与别人无关？","hint":""},{"question":"群体中谁可能因照顾责任、经济压力、病痛或冲突而逐渐孤立？","hint":""},{"question":"哪一次别人的鼓励曾使我重新站起来？","hint":""}],"practices":["具体询问一个人的处境和实际需要，而不只问他是否参加聚会。","若自己的盼望变弱，向群体诚实说明，不必假装刚强。"],"prayer":"感谢神借着群体扶持我们的信心。\\n求主使我成为能激发爱心和善行的人。\\n求主帮助我们用合宜方式保持联系，不让疲惫的人独自退后。"}},{"day":21,"chapter":10,"title":"不退后 在忍耐中活出信心","key_verses":"来 10:26-39","story_section":"新约","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第10章严肃警告，不要轻看明知真道却故意持续犯罪的事。这并非指日常生活中每一个错误或一时的软弱。问题在于，人明知耶稣已经开通道路，却故意弃绝他的教导，把别的安全保障、权势或宗教秩序当作终极盼望，持续朝那个方向走。作者用审判的火和可怕的等候等法庭语言唤醒听众，使他们不把自己的选择当作小事。前面邀请人坦然来到神面前，绝不是叫人轻看罪和责任。\\n\\n10章29节使用践踏神的儿子、轻看立约之血、侮辱赐恩典的圣灵等十分强烈的表达，显明人认识耶稣的道路，却仍固执选择仇恨和不义，是多么严重。若一面说相信耶稣的牺牲，一面不断伤害弱者、掩盖真相，毫无回转之意，只要求别人原谅，就不能回避这警告。救恩不是一个人在故意悖逆时仍可一直保有的称号，而是顺服耶稣的话，把生命与公义的道路走到底的生活。\\n\\n不过，作者没有立刻判定读者已被弃绝，反而引导他们回想初信的时候。他们曾忍受羞辱和患难，与被囚的人一同受苦，也甘愿承受财产被夺。作者提起过去的付出，不是要羞辱他们，追问为什么从前做得到、现在却不行，而是要重新唤起当时的勇气、连结和爱，帮助他们胜过眼前的疲惫。他把警告与美好的记忆放在一起，重新建立群体。\\n\\n10章35节不要丢弃勇气的劝勉，不是说人不能害怕，或应当无视危险，而是说，即使惧怕，仍要遵行神的旨意，忍耐前行。作者引用《哈巴谷书》中义人因信而活的宣告，把退后的道路与通向生命的信心之路相对照。对当时的听众来说，退后可能意味着，为了取得地上圣殿的认可和社会的安全，而放弃耶稣的道路。信心不只停留在起初的热情，而是在压力中仍守住正确方向的顺服。\\n\\n有人说，只要相信耶稣为我的罪死了，我就得救；他们的意思是，人不是凭行为，而是凭信心得救。然而，今天的经文说，违背摩西律法的人尚且受到严厉惩罚，违背那位比摩西更伟大者的话，岂不更要受罚？我们可以说，自己为过去的罪悔改，借着耶稣为赐我们生命而传讲神的话、因此受难所成就的工作，已经蒙了拯救。但今天的信息也告诉我们，神必审判此后所犯的罪。不能只想到神有恩典，就轻忽这件事。经历过恩典的人，更应竭力忠心走耶稣所指明的道路。","prayer":"天父，我把那些在压力中疲惫、心里想要退后的弟兄姊妹交托给您。求您唤起他们曾经信靠您的勇气，使他们重新得力，也认真面对今天的选择。愿您的警告唤醒固执的心，愿您的怜悯扶起愿意回转的人。求您赐我智慧，分辨弟兄姊妹的软弱和难处，以爱心劝勉、耐心扶持。愿我们在惧怕中仍守住诚实与公义，一同忍耐前行。阿们。"},"handbook":{"today_focus":"明知真道却故意持续选择不义，是必须严肃面对的事；恩典不能成为拒绝悔改的借口。与此同时，作者提醒读者过去的勇气和爱，帮助他们在失败后重新站起，继续遵行神的旨意。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"这一段用哪些强烈图像警告故意持续犯罪？"},{"question":"作者为什么又让听众回想从前忍受患难和彼此相顾的日子？"}],"meditations":[{"question":"我是否用\\"神有恩典\\"合理化一项反复伤害人的行为？","hint":""},{"question":"哪些顺服即使在压力中也不能放弃？","hint":""},{"question":"过去哪一次忍耐、分享或与受苦者同行，可以成为我今天重新得力的记忆？","hint":""}],"practices":["清楚分辨一个需要立即停止或纠正的行为。","回想并写下过去一段忠心经历，用它提醒自己不要退后。"],"prayer":"求主使我认真面对故意悖逆的严重性。\\n感谢神没有忘记我曾经付出的爱和忍耐。\\n求主赐我在惧怕中仍遵行他旨意的信心。"}},{"day":22,"chapter":11,"title":"信靠那尚未看见的应许而前行","key_verses":"来 11:1-7","story_section":"信心的忍耐","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第11章所说的信心，不是凭心念的力量实现愿望，也不是毫无分辨地把一切看不见的事都当作事实。第1节把信心与尚未实现的盼望、眼睛看不见的事相连，为接下来的信心人物故事开路。即使神的应许尚未在眼前实现，信心仍真诚信靠它，因此今天作出不同的选择。这并非确信自己知道未来所有结果，而是信靠神的品格和话语，今天就顺服。\\n\\n承认世界由神的话造成，就是承认眼前的现实并非全部。今天看似强大的制度和权势，也不是永恒不变的实在。那看不见的神的旨意和治理，才是世界更深的根基。亚伯献上更美的祭，以诺与神同行、蒙神喜悦，挪亚听见关于尚未看见之危险的警告，便预备方舟。他们不只在心里相信，更以时间、财物和行动实践神的话。\\n\\n亚伯的献祭、以诺的同行、挪亚的预备，形式不同，却都是出于信心的顺服。信心不是预知一切结果，也不是永不失败的能力，而是沿着神指明的方向，做好今天当做的事。因此，经文说，来到神面前的人，必须相信神存在，也相信他赏赐寻求他的人。这里的赏赐，并非保证人凡有所求都能得到，而是应许寻求、顺服神的人，能有分于他的生命和他所预备的将来。\\n\\n对当时的听众来说，看得见的圣殿和强大的民族群体所提供的安全，十分现实，也很有吸引力。但《希伯来书》劝他们，把看不见的神的应许视为更可靠的依靠，继续走耶稣的道路。信心不否认现实，却也不以眼前的成功和安全作最终准则，而是顾念神的审判与将来的生命，为今天的选择负责。挪亚预备方舟，也不只是被恐惧驱使，抛下世界、只顾自己一家，而是把所听的话，化为长期的劳动和对家人的责任。\\n\\n神借着《希伯来书》的作者告诉我们，即使结果尚未显明，以诚实和爱所付出的辛劳也不会徒然。神所喜悦的，不只有眼前的成功，也包括那信靠尚未看见的应许、愿意预备和等候的信心。若有一直拖延的责任，不要灰心，重新站起来，从小事开始。同时，不要因为成果没有立刻出现，就轻看自己或别人的信心。一个相信尚未实现之应许的群体，会看见那些默默持续的忠心，彼此鼓励。","prayer":"天父，我为那些努力已久，却仍看不到结果的弟兄姊妹祷告。求您使他们信靠您的品格和应许，安稳地做好今天该做的事，不以暂时的成功或失败判断自己整个生命。愿有人理解他们的辛劳，珍惜每一点忠心。也求您赐我眼光，看见他们默默坚持的善行，与他们一同感恩，继续前行。阿们。"},"handbook":{"today_focus":"信心不是用意志实现愿望，而是因为信靠神的品格和应许，在结果尚未显明时就作出顺服的选择。亚伯、以诺和挪亚的信心都落实在献上、同行和长久预备中。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"第1节怎样描述信心？"},{"question":"亚伯、以诺和挪亚各自以什么行动显出信心？"}],"meditations":[{"question":"我是否把信心等同于\\"我相信想要的结果一定会发生\\"？","hint":""},{"question":"在尚未看见结果的事情上，今天可以开始哪一步？","hint":""},{"question":"我是否只看重立刻可见的成果，却忽视默默持守、长久不变的忠心？","hint":""}],"practices":["确认必要信息后，从一个具体的小行动开始。","肯定一位尚未看见成果、却持续忠心预备的人。"],"prayer":"感谢神的应许比眼前处境更可靠。\\n求主使我的信心落实为今天的行动。\\n求主帮助我不以眼前的成果衡量自己和别人。"}},{"day":23,"chapter":11,"title":"仰望家乡 在地上作客旅","key_verses":"来 11:8-22","story_section":"信心的忍耐","letter":{"body":"亲爱的弟兄姊妹：\\n\\n亚伯拉罕蒙召的时候，虽然不知道要往哪里去，却仍顺服。到了应许之地以后，他也继续住在帐篷里。撒拉面对自己的年纪和身体限制，也曾在神的应许面前动摇，却仍倚靠那位应许者的信实。他们直到去世，都没有看见一切应许完全实现，只从远处望见，欢喜迎接，承认自己在地上是客旅、是寄居者。《希伯来书》没有把这样尚未圆满的一生看作失败，而是把它呈现为按应许继续前行的信心。\\n\\n作客旅，不是要轻看现实生活，放下对家庭和社会的责任。亚伯拉罕照顾家人、调解争端，也为安葬撒拉，按商定的价格买下土地。他承担具体责任，同时知道眼前的财产和地位，并非自己最终的身份。因此，他不把土地和财富绝对化，仍继续仰望神所预备的未来。向往家乡的信心，不是敷衍度日，而是不被财物捆绑，忠心维系眼前的关系，履行已经许下的承诺。\\n\\n作者把应许之地的故事，扩展到更美的家乡，以及神所设计、建造的城。这不是嘲笑或取消以色列对土地和复兴的期待，而是不把神的应许局限在一次政治复兴或建筑恢复中。人不必等到圣殿和国家恢复，才能成为神的子民。对于那些按应许顺服、不过分依附眼前城市的客旅群体，神并不以他们为耻。听众应当仰望将来神的城，而不是为了社会保障放弃耶稣的道路。\\n\\n亚伯拉罕、以撒、雅各和约瑟，都没有在自己一生中看见应许完全实现，却仍祝福下一代。约瑟临终时，谈到以色列将来要走的路，并嘱咐后人带着他的骸骨离开。信心不是急着要求一生之内看见所有结果，而是把正确的方向和责任留给后来的人，使他们继续前行。群体的领袖不能只想着留下自己的名声和成就，也应分享位置和智慧，让下一代能够更自由、更忠心地服事。\\n\\n有些弟兄姊妹热心服事教会，却因迟迟看不见美好的果子而失望，甚至怀疑自己和教会是否正在遵行神的旨意。但我们所做的服事，正是神吩咐的爱神、爱邻舍。让我们不再被这疑虑困住，怀着盼望，继续热心为神的国付出，相信神必使这些服事结果。让我们寻求神的智慧，以更有创意、更有效的方式，承担手中的工作。","prayer":"天父，我记念那些热心服事、却迟迟看不到果子而灰心的弟兄姊妹。求您安慰他们，使他们把尚未实现的盼望交托给您，安稳地承担今天的责任。愿我们向往您所预备的家乡，也珍惜眼前的人，用心履行自己的承诺。求您赐我们智慧，学习更合适的服事方式；也帮助我分享经验、腾出位置，扶持下一代继续走信心的道路。阿们。"},"handbook":{"today_focus":"信心之人没有在一生中得到全部应许，却仍承担现实责任，并把正确方向留给下一代。客旅身份不是逃避今天，而是不把财物、地位和眼前城市当作最终归属。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"亚伯拉罕蒙召后怎样生活在应许之地？"},{"question":"这些人临终时怎样继续指向尚未完全实现的应许？"}],"meditations":[{"question":"我在哪一种环境中感到自己不完全属于这里？","hint":""},{"question":"我是否把财物、房产、身份或地位当成最后的安全？","hint":""},{"question":"我应当把哪些经验、责任或服事机会分享给后来的人？","hint":""}],"practices":["在现居之地忠实履行一个合同、承诺或邻舍责任。","为一个新来、孤单或不熟悉环境的人留出实际帮助。"],"prayer":"感谢神为我们预备更美的家乡。\\n求主使我不轻看今天的责任，也不被眼前拥有的一切捆绑。\\n求主帮助我把信心的方向和责任交给下一代。"}},{"day":24,"chapter":11,"title":"摩西选择神的子民 胜过法老的宫廷","key_verses":"来 11:23-31","story_section":"信心的忍耐","letter":{"body":"亲爱的弟兄姊妹：\\n\\n摩西的父母不怕王命，把婴儿藏起来。摩西长大以后，也没有继续享受法老女儿之子的身份和特权，而是选择与神的子民一同受苦。《希伯来书》说，他不贪恋罪中暂时的享乐，愿与神的百姓一同承担责任。他看重的，不是眼前君王的震怒，而是那看不见的神，以及将来的赏赐。信心并非完全不关心安全，而是以行动选择，什么才是真正可靠的保障。\\n\\n这故事并非美化苦难本身，也不是责备所有选择安稳生活的人。摩西选择的不是无意义的痛苦，而是不愿为了自己的成功和安全，对受压迫的人视而不见。他原本可以保住宫廷特权，漠视同胞的苦难，却选择承担自己的身份和责任。信心也包含这样的选择：不只计算个人利益，愿意站在弱者身旁，放下从不义结构中得来的好处。\\n\\n作者把摩西承受的羞辱与基督相连（11:26），并不是说历史中的摩西已经知道耶稣的名字，以及十字架的一切细节，而是把他放下宫廷特权、站在受苦百姓身旁的道路，与耶稣在城门外受辱的道路一同阅读。这样，过去的故事就成为一面镜子，照见今天的选择。\\n\\n逾越节和过红海，也不是毫无恐惧的英雄故事。以色列人按神的话把血涂在门框上，朝着红海迈步，借着这些行动有分于神的拯救。喇合也冒着危险，和平地接待探子，进入新的群体。出身和过去没有成为她被排除在救恩之外的理由，她保护生命的行动也被记为信心。这段经文看重的，是人是否信靠神、以行动回应，而不是出身。摩西和喇合的故事，让我们看见信心的顺服超越身份与背景，并显明在危机中保护谁的生命、向哪个群体忠心。\\n\\n有人认为，凡是进展顺利的事，就是神所喜悦、神与之同在的事。然而，今天经文中的摩西和喇合，都凭着信心作了可能危及性命的艰难选择，圣经也把他们列为伟大的信心人物。愿今天的信息，为那些在困难的小组或地方教会处境中，仍默默承担责任的人带来神的安慰。也愿你们为神和他的教会所付出的努力不至徒然，最终像摩西和喇合那样，得着美好的结果。愿神帮助正在忍耐、坚持的你们。","prayer":"天父，您知道这些弟兄姊妹为持守信仰、照顾群体所付出的辛劳。求您特别扶持那些处境艰难、仍默默承担责任的人，使他们知道，自己的忠心蒙您记念。面对利益和压力，求您赐我们勇气与智慧，愿意站在受苦的人身旁，保护生命，寻求合适的帮助。求您也使我看见他们的重担，尽我所能与他们分担。愿我们在您的看顾中，继续忠心前行。阿们。"},"handbook":{"today_focus":"摩西的信心显在：他不愿为保全个人的安全而对受压迫者视而不见；喇合的信心也显在危机中保护生命。信心会问：我在保护谁，又把自己的安全和影响力用于什么？","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"摩西为什么拒绝继续以法老女儿之子的身份生活？"},{"question":"逾越节、过红海和喇合接待探子的行动怎样表现信心？"}],"meditations":[{"question":"我是否从某种不义结构中得到好处，却不愿正视那些因此受到伤害的人？","hint":""},{"question":"我手中的安全、资源或影响力，可以怎样保护一个较弱的人？","hint":""},{"question":"为了公义与人站在一起时，我需要哪些同伴，而不是独自作英雄？","hint":""}],"practices":["支持一个平时缺少权势之人的合理意见。","与可靠同伴商量一项保护生命、分担风险的具体行动。"],"prayer":"感谢神记念为保护生命而迈出的信心脚步。\\n求主使我不为个人安全出卖公义和关系。\\n求主赐我智慧，与同伴一起承担而不是孤军奋战。"}},{"day":25,"chapter":11,"title":"经历胜利与苦难的信心见证人","key_verses":"来 11:32-40","story_section":"信心的忍耐","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第11章最后，把经历截然不同结果的人列在同一份名单中。有些人征服列国、施行公义、得着应许，堵住狮子的口，脱离残暴的势力；另一些人却遭受嘲弄、鞭打、监禁、酷刑和死亡，在旷野、山岭和洞穴中漂泊。同样的信心，并不总带来同样看得见的结果。作者把得胜者和被杀者都称为信心的见证人，使我们不能把信心当作保证成功的公式。\\n\\n经文迅速列举一连串得胜的故事，随即转向另一些人的苦难。这有意的转折，打破了只要信神就一定健康、富裕、事业成功的想法。信心不是利用神取得理想结果的技巧，而是即使看不见结果，处境甚至更坏，仍忠于神关于生命与公义的旨意。有人因顺服脱离危机，也可能有人因同样的顺服，承担更大的危险。\\n\\n受苦的人盼望更美的复活，并不是轻看当下的伤痛，也不是要求人默默忍受暴力。他们遭受的酷刑、失去和死亡都是真实的，也是明确的恶。他们相信，即使暴力夺去生命，自己的命运也不会就此结束。他们怀着神要使死人复活、纠正所受不公的盼望，持守信心到底。若只向受害者谈未来的补偿，却漠视他们现在所需的保护和帮助，就是歪曲经文。复活的盼望，使我们今天抵抗不义，站在受苦的人身旁。\\n\\n作者说，这些人虽因信得到神的认可，却仍在等候应许完全实现。神预备了一个将来，使不同世代的信徒一同达到完全（11:39--40）。信心的道路，不是争当独行英雄的竞赛，而是许多世代和群体一同等候成全的路。一个人的忍耐与顺服，为后来的人开路；今天群体的选择，也延续着前人作见证的故事。听众不能把自己的苦难看作独自承担、最终失败的事，而应知道，自己是历代信仰群体中的一员，与其他肢体彼此相连。\\n\\n群体里应当既容得下生意好转的喜乐，也容得下久候医治的眼泪；既有升职者的感恩，也有失业者的惧怕。不要因为一个人长久看不见期待的结果，就断定他缺乏信心。神不只记念得胜的人，即使尚未看见应许完全实现，他也记念那些忠心到底的人，称他们为信心的见证人。今天的顺服即使没有立刻带来理想结果，也不要灰心，继续实践现在能做的诚实与爱。一个既同庆喜乐、也陪伴流泪之人的群体，才能一同延续信心的故事。","prayer":"天父，我们把欢笑的弟兄姊妹和流泪的弟兄姊妹，一同带到您面前。感谢您赐下的帮助与喜乐，也求您扶持仍在疾病、失去和长久等待中的人。不要让他们因为尚未看见盼望的结果，就以为自己被您忘记。愿我们愿意一同庆祝，也愿意陪伴流泪的人。求您以复活的盼望坚固他们，使我们在不同处境中仍彼此相爱，持守信心。阿们。"},"handbook":{"today_focus":"同样的信心可能带来不同的可见结果：有人得胜，有人却受苦甚至被杀。神不只记念成功者，也记念那些没有在今生看见应许完全实现、却忠心到底的人；复活的盼望使我们抵挡不义并陪伴受苦者。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"这一段怎样从得胜的故事转向受苦的故事？"},{"question":"受苦者仰望\\"更美的复活\\"说明他们相信什么？"}],"meditations":[{"question":"我是否把健康、财富或成功当作衡量信心的标准？","hint":""},{"question":"群体中谁正处在迟迟没有好结果的等待或痛苦中？","hint":""},{"question":"复活的盼望和对神终必伸张公义的信靠，怎样帮助我今天不向不义妥协？","hint":""}],"practices":["既为一个人的喜乐庆祝，也为另一个人的眼泪留出时间。","不要只谈将来的盼望；确认受苦者今天需要的安全和帮助。"],"prayer":"感谢神记念得胜者，也记念受苦而忠心的人。\\n求主使我不以结果论断别人的信心。\\n求主借复活的盼望，使我今天抵挡不义、陪伴受苦者。"}},{"day":26,"chapter":12,"title":"仰望耶稣 忍耐奔跑","key_verses":"来 12:1-3","story_section":"信心的忍耐","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》第12章描绘一个赛场，有许多如云彩般的信心见证人围绕着我们。这并不是说，他们在天上监视我们的行为，为我们打分；更贴近经文的理解是，他们的一生证明，信心的道路确实可以走到底。走在前面的人，也曾在没有看见一切应许实现时顺服。如今，我们也应放下重担和容易缠累我们的罪，忍耐奔跑前面的信心赛程。我们从不同的位置出发，却不是独自开辟一条从未有人走过的路。\\n\\n使我们疲惫的，不全是罪或错误。照顾家人、认真工作、服事群体，都是宝贵的责任。但即使是好事，若承担得太多，超出能力，身心也会耗尽，难以继续走神交托的信心之路。想满足所有人的期待、过量工作、不断比较、渴望被肯定，也会使脚步沉重。放下重担和缠累之罪的劝勉（12:1），并非要我们突然抛弃一切责任，而是像长跑者放下多余的负重一样，分辨哪些需要承担，哪些应当放下，好凭信心走到底。\\n\\n在这场赛程中，重要的不是不断衡量自己的意志有多强、成就有多大，而是仰望耶稣。他开启信心的道路，也使信心达到完全。他先走过这条路，顺服到底。经文说，他因前面的喜乐忍受十字架，轻看羞辱，并不是说痛苦很轻、羞辱无足轻重，而是说，痛苦和社会的排斥，都不能使他放弃神的旨意。仰望耶稣，不只是反复思考关于他的知识，更是把他在苦难中所选择的顺服，作为我们生活的准则。\\n\\n这番劝勉，是给那些因压力和疲惫而想退后的群体。若为了看得见的宗教荣耀和社会保障，放弃耶稣的道路，就会在信心的赛程中失去方向。忍耐不是漫无方向地长久硬撑，而是以耶稣关于生命与爱的旨意为准则，守住正确的道路。独自背负所有重担直到倒下，也不能称为忍耐。群体应当分担重担，调整步调和责任，使软弱的人也能继续前行。\\n\\n疲惫了、脚步慢了，并不表示信心失败。不要拿自己的速度与别人比较。本周的安排里，可以放下一件并非非做不可的事。若累得难以判断，休息和求助，也是跑完全程所需的智慧。对于使你反复跌倒的习惯，可以与可信任的人制定具体计划，逐步改变。但不要每次失败就定自己的罪，逼着自己继续向前冲。仰望那位开启并成全信心的耶稣，我们跌倒后仍能站起，重新得到方向和继续奔跑的力量。","prayer":"天父，我们记念那些承担太多、已经无力奔跑的弟兄姊妹。求您帮助他们分辨该承担的责任和可以放下的重担，也预备愿意分担的人。愿他们在休息和接受帮助中重新得力，仰望耶稣，继续前行。求您使我不拿别人的速度催促他们，而是耐心陪他们走。愿我们放下缠累，一同走完您摆在前面的道路。阿们。"},"handbook":{"today_focus":"信心像一场需要忍耐的长跑。为了走到底，我们既要脱去缠累人的罪，也要分辨那些虽不一定错误、却已使身心耗尽的负担；真正的方向和力量来自仰望在苦难中顺服到底的耶稣。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"\\"许多见证人如同云彩\\"在这一段承担什么作用？"},{"question":"作者吩咐跑者脱去什么，又把目光放在哪里？"}],"meditations":[{"question":"目前哪些责任必须承担，哪些负担其实可以减少、分享或放下？","hint":""},{"question":"我是否因比较、满足所有人的期待或渴望肯定而脚步沉重？","hint":""},{"question":"反复使我跌倒的习惯，需要怎样的具体计划和可靠同伴？","hint":""}],"practices":["从本周安排中放下一项并非必须由你承担的事情。","与可靠的人制定一个可实行的小计划；失败时不定自己的罪，而是重新开始。"],"prayer":"感谢耶稣已经走完信心的道路。\\n求主赐我分辨责任和无谓重担的智慧。\\n求主使我跌倒后仍能仰望耶稣，再次站起来前行。"}},{"day":27,"chapter":12,"title":"在管教中重新站稳软弱的腿","key_verses":"来 12:4-17","story_section":"信心的忍耐","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》引用《箴言》，向忍受苦难的读者讲论神的管教。其中包含父母教导、训练孩子，纠正错误，使其成熟的意思。当时的群体可能因外在的羞辱和损失，以及内部的疲惫，觉得自己被神弃绝。但作者没有把他们遭遇的一切苦难，都解释为某项罪的惩罚，而是说，即使在艰难中，他们仍能学习神的旨意，结出公义与平安的果子。因此，我们不能断定每一场疾病和意外，都是神因某个人的罪而降下的惩罚。\\n\\n管教在当下并不令人愉快，甚至使人痛苦，但它的目的，是引人走向成熟和生命，而不是摧毁人。绝不能因此用这段经文为父母或领袖的暴力辩护，也不能替教会中的虐待和控制开脱。人的暴力必须停止。受害者应当保持安全距离，寻求保护，以及法律、医疗和专业帮助。加害者声称是因为爱才管教，并不能使他的行为变成神的管教。神的管教引向公义和平安，虐待却使人陷入恐惧和沉默。\\n\\n经文劝我们举起下垂的手，挺直软弱的腿，为自己的脚修直道路。群体的责任，不是命令受伤的人跑得更快，或责备他们信心不足，而是修平道路，帮助他们恢复，避免伤害加深。这也包括分担难以承受的重担，安排必要的治疗和休息。指出错误时，不应公开羞辱或威胁，而应清楚说明错在哪里、造成了什么伤害，以及需要承担哪些责任、怎样走向恢复。管教的目的，是帮助人回到正路，而不是把人逐出群体。\\n\\n努力与众人和睦的劝勉（12:14），也不是要掩盖不义、保持沉默。要使苦根不伤害整个群体，就必须诚实处理伤害和错误。圣洁不只是表面没有冲突，更是在关系中选择真实与责任。以扫的故事警告我们，不要因片刻的饥饿和欲望，轻易卖掉应当长久守护的责任与福分。当时的听众同样不能为了眼前的安全，放弃耶稣的道路和将来的应许。\\n\\n重新站稳软弱的腿，不是要求受伤的人独自承担恢复的责任。神盼望群体修平道路、分担重担，使疲惫的人重新站立。请分辨，眼前的困难是需要忍耐学习的管教，还是应当立即脱离的虐待。若处境危险，不要独自忍受，要向安全、可信赖的人和专业机构求助。也请继续做那些帮助身心恢复的小事，例如睡眠充足、规律饮食，向可信任的人坦诚讲出自己的难处。神所盼望的果子，是公义、和平与恢复，而不是恐惧和沉默。","prayer":"天父，我们把受伤、疲惫的弟兄姊妹，以及仍在学习过程中的弟兄姊妹交托给您。求您赐下分辨力，使他们接受真诚的劝勉，也能离开有害的处境，寻求保护。愿我们的群体修平道路、分担重担，帮助软弱的人重新得力。也求您保守我，不用羞耻和恐惧逼迫他们。愿您的教导在我们中间结出公义、平安和成熟的果子。阿们。"},"handbook":{"today_focus":"神的管教旨在带人走向成熟、公义和平安，绝不能被用来合理化暴力、虐待和控制。群体的责任不是催促受伤者跑快一点，而是修平道路、分担重担，并帮助人获得安全和恢复。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"箴言中\\"管教\\"的目的是什么？"},{"question":"经文怎样把管教与\\"公义的果子\\"\\"和平\\"联系起来？"}],"meditations":[{"question":"眼前的困难是需要耐心学习的训练，还是必须立即离开的虐待或危险？","hint":""},{"question":"我们的群体在哪些地方使受伤者更难说话、求助或恢复？","hint":""},{"question":"我是否用\\"为了你好\\"掩盖控制、羞辱或不当的要求？","hint":""}],"practices":["若处境危险，立即向安全可信的人和专业机构求助，不要独自忍受。","以足够睡眠、规律饮食和诚实对话，继续做帮助身心恢复的小事。"],"prayer":"求神使我认识他的管教不是摧毁，而是带向生命。\\n求主保护受伤和受虐待的人，赐他们安全的帮助。\\n求主使群体修平道路，结出公义、和平与恢复的果子。"}},{"day":28,"chapter":12,"title":"来到锡安与那不能震动的国","key_verses":"来 12:18-29","story_section":"不能震动的神国","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》把西奈山令人惧怕的景象与锡安山的喜乐相对照。西奈山有烈火、密云、黑暗、风暴、号声和可怕的声音，百姓无法靠近；锡安山则有永活神的城、天上的耶路撒冷、无数天使欢聚的盛会，以及达到完全的义人之灵。作者不是在介绍两个地方的旅游资料，而是把圣经中的两个场景并列，说明跟随耶稣的群体怎样来到神面前。\\n\\n这对照并不是简单区分，旧约的神令人惧怕，新约的神充满慈爱。在西奈山和锡安山说话的，是同一位圣洁的神。不同之处在于，耶稣成为中保，以血确立新约，为整个群体开通了亲近神的道路。亚伯的血控诉杀人之罪，耶稣的血却开出怜悯、和好与重新顺服的道路，而不是让暴力报复不断延续。但神的怜悯没有取消他的圣洁和公义审判。因此，作者仍警告我们，不要拒绝那位向我们说话的主。\\n\\n经文说，读者已经来到锡安山，表明这已经发生。其中也含有劝勉：不要只是等待将来某一天圣殿和耶路撒冷恢复。即使地上可见的城失去力量，群体被挤到社会边缘，只要听从耶稣的话、彼此帮助、活出生命、顺服神，就已经有分于他的治理。同时，天上的城和完全的聚集，也是将来要充分显明的应许。今天的参与与将来的完成并存，因此，群体既不应因眼前的挫折而绝望，也不能自满地以为一切已经完全实现。\\n\\n神宣告，他要再次震动天地，使一切能被震动的显露出来。这不是预言某一天会发生一场特定地震，而是说，即使人视为永久依靠的制度、权势和财产，也可能在神的审判前倒塌。赐给顺服之人的不能震动的国，并不保证眼前的国家或教会制度永远存在，而是应许神公义、生命与爱的治理存留到底，遵行他旨意的人将有分于这国。\\n\\n在动荡的现实中，请记住12章22节的信息：借着耶稣，我们已经来到锡安山。即使现实艰难、令人不安，借着耶稣亲近神的道路仍然敞开。我们属于不会消失、不会倾覆的神国，等候它完全显明的日子。今天，为这盼望感谢神，也请省察，自己是否为了保住面子和财物，牺牲真相或弱小的人。即使在小小的群体里，我们也应说真话、保护被排斥的人，并且行善。感谢和敬畏，会显明在日常生活中：信靠神不能震动的治理，顺服他的旨意。","prayer":"天父，感谢您赐下不能震动之国的盼望。我们记念那些因环境动荡、失去原有保障而不安的弟兄姊妹。求您使他们沿着耶稣开通的道路亲近您，得到持守诚实与爱的力量，不因害怕失去财物和面子，就牺牲弱小的人。愿我们怀着感谢和敬畏彼此帮助，在今天的生活中见证您的治理，等候应许完全显明的日子。阿们。"},"handbook":{"today_focus":"借着耶稣，群体已经有路来到圣洁的神面前，也属于那不能被制度、权力和财物的震动摧毁的神国。这个盼望带来感谢，也带来敬畏和顺服。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"作者怎样对比西奈山和锡安山？"},{"question":"\\"再一次震动天地\\"要显明什么？不能震动的国指向什么？"}],"meditations":[{"question":"当前哪些不稳定的现实最使我害怕？","hint":""},{"question":"我是否为了保住面子、地位或财物，牺牲真相或软弱的人？","hint":""},{"question":"\\"已经来到锡安\\"给今天的小群体怎样的盼望和身份？","hint":""}],"practices":["为借着耶稣亲近神、属于神国的盼望献上感谢。","在一个具体处境中说实话、保护被排斥的人或坚持行善。"],"prayer":"感谢神使我们借着耶稣来到他面前。\\n求主使我不把会震动的事当作永恒依靠。\\n求主使我以敬畏和感恩顺服他公义、生命与爱的统治。"}},{"day":29,"chapter":13,"title":"弟兄相爱 接待客旅 知足生活","key_verses":"来 13:1-6","story_section":"不能震动的神国","letter":{"body":"亲爱的弟兄姊妹：\\n\\n前面详细论述圣殿和祭司之后，《希伯来书》在最后一章转向非常具体的生活劝勉：持续彼此相爱，接待客旅，记念被囚和受虐待的人，因为我们自己也有同样的身体。信心不能停留在讨论天上的圣所和永远的大祭司，怎样对待身旁之人的身体和需要，才显明其真实。继续弟兄相爱的劝勉（13:1），表明群体已经实践过爱，只是疲惫和危险可能使这爱渐渐减弱。\\n\\n古代旅人不像今天这样，容易找到安全住所或公共援助。因此，接待客旅不只是表达友善，也是保护生命。13章2节提到，有人接待陌生人，却在不知不觉中接待了天使。这并非说每个客人都会带来特别的报偿或好运，而是让人想起亚伯拉罕和罗得接待陌生访客的故事，强调即使不知道对方是谁，所给予的照顾在神面前也很重要。接待客旅，也不是毫无界限地让陌生人进家门，而是在维护安全的同时，尊重外来者，帮助他获得所需的支持。\\n\\n记念被囚之人的劝勉，要求当时的信徒与那些因信仰受辱、受罚的人保持实际联系。送去食物和衣物、维持关系的人，也要承担风险。经文引导我们把受苦者的处境当作自己的事来体会（13:3），不把别人的痛苦当作遥远的消息，而是设身处地思想、行动。今天的联系同样不能只停留在好意上，也包括给新来的人提供生活信息，为处于危险的人联系医疗、法律和住宿援助，以及帮助长期照顾家人的人真正得到休息。\\n\\n尊重婚姻、不贪爱钱财的劝勉（13:4--5），都与关系中的忠诚有关。情欲和贪婪会使人把别人当作满足自己、获取利益的工具，进而违背承诺。知足并不是把贫穷、工资剥削和不公看作理所当然，也不是不许求助，而是不要相信财物决定人的价值和安全。我们可以向群体说明正当需要，有余力的人也应乐意分享。神绝不离弃我们的应许，并非空泛的安慰；当我们因恐惧想出卖关系和公义时，这应许使我们有力量持守到底。\\n\\n继续弟兄相爱，再次表明群体已经实践过爱与接待。今天，请想想谁曾照顾你，群体一直坚持哪些善行，为此感谢神。不要让疲惫截断爱，可以向身旁的人分享所需的信息、一顿饭，或有助于安全的支持。分享资源时，也要尊重对方的选择，不随意把他的困难告诉别人。对家人的承诺，以及自己应当承担的责任，也要认真履行。神不离弃我们的应许，使我们不因恐惧放弃关系和公义，而能继续相爱。","prayer":"天父，感谢您借着弟兄姊妹的爱和照顾扶持我们。求您看顾孤单的客旅、被囚和受苦的人，使他们得到实际的关怀。愿我们的家庭信守承诺，也愿我们把手中的财物与有需要的人分享。求您使我记得那些默默付出的人，体察他们的疲惫。愿您不离弃我们的应许，保守我们不被贪婪和恐惧牵引，继续彼此相爱。阿们。"},"handbook":{"today_focus":"信仰的真实性显在我们怎样对待身边人的身体、需要、关系和承诺。接待与分享需要安全、尊重和保密；知足也不是默许贫穷和剥削，而是不让金钱决定人的价值和忠诚。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"这一段连续提到哪些具体生活关系和责任？"},{"question":"\\"神不撇下你，也不丢弃你\\"的应许如何支持前面的劝勉？"}],"meditations":[{"question":"我曾从谁得到接待、照顾或实际帮助？","hint":""},{"question":"我分享资源时，是否尊重对方的选择、隐私和界限？","hint":""},{"question":"我是否因惧怕金钱不足，而忽略家庭承诺、关系忠信或公义？","hint":""}],"practices":["分享一项实际帮助：信息、一顿饭、陪同或安全的资源。","守住受助者的隐私，也认真履行对家人已经许下的承诺。"],"prayer":"感谢神借着人的爱和接待照顾我。\\n求主使我在分享时尊重人，不控制、不炫耀。\\n求主使我因他不离弃的应许，继续忠于关系和公义。"}},{"day":30,"chapter":13,"title":"走到城门外 献上赞美与善行的祭","key_verses":"来 13:7-25","story_section":"不能震动的神国","letter":{"body":"亲爱的弟兄姊妹：\\n\\n《希伯来书》劝我们察看带领群体之人的生活结出怎样的果子，效法他们的信心。这不是要人不加分辨地跟随领袖，也不是把过去的领袖塑造成完美人物，而是把他们所传的神的话与实际生活的果子放在一起，效法他们忠于耶稣道路的样式。耶稣基督昨日、今日、直到永远都一样。因此，群体的中心应当是耶稣的话和他走过的道路，而不是会改变的人间领袖、组织传统或时代潮流。\\n\\n作者劝我们，不要被各样陌生的教训带走，要靠恩典坚固内心，因为饮食条例和凭外在标准划分人的方式，不能成为使人完全的最终依据。随后，他强调耶稣在城门外受苦，劝我们到营外去，来到他身旁，一同承担羞辱（13:13）。当时，得到圣殿和圣城中心的接纳，仿佛就是安全和得救的标志。因此，到被弃绝、在城外受苦的耶稣那里去，是一个强烈的邀请，要人重新决定把忠诚和荣耀放在哪里。\\n\\n这不是要人仇恨犹太人或社会，建立封闭的群体，也不是要求人真的离开所住的城市。作者把祭牲的身体在营外处理，与耶稣在城门外被弃绝的场景联系起来，劝人不要以安全的宗教荣耀为首要追求，而要站在受苦、被排斥的耶稣身旁。13章14节提醒我们，地上的城不会永远存留。这并非叫我们放弃对所在国家、城市和群体的责任，而是警告我们，不要把任何圣殿、教会制度、国家或领袖当作神国本身。我们应仰望将来的城，不把眼前的权势绝对化。\\n\\n如今，群体所献的祭，不是动物的牺牲，而是借着耶稣向神献上嘴唇的赞美，在生活中行善，并分享所有。敬拜和赞美，不能与帮助受苦邻舍的行动分开。领袖也不是控制人的掌权者，而是受托照顾人的生命，并要为自己的生活和决定向神负责的人。信徒不应无端怀疑领袖，却可以察看他们是否使人得益、持守真实，并提出必要的问题。顺服应当发生在彼此负责、坦诚沟通的关系中。\\n\\n请为这三十天一同默想神的话、彼此同行的时光感谢神。即使不能完整记住所有内容，那些触动内心的话，以及刚刚开始的小小顺服，也会留在心里，照亮前面的路。请写下一句这次默想中最深留在心里的话，以及一种愿意继续坚持的生活习惯。不要只寻找得到人认可的位置，也要走到耶稣所在的城门外，献上赞美、善行和分享的祭。愿神装备你们，使你们行各样的善事；也愿他继续引导我们，即使相隔遥远，仍作为一个彼此建立的群体生活。","prayer":"天父，感谢您陪伴这些弟兄姊妹走过三十天的默想。我不能时刻在他们身旁，却把每一个人交托给您。愿所领受的话留在心里，结出赞美、善行和分享的果子。也求您保守我的心，使我继续以温柔和诚实与他们同行。愿我们跟随群羊的大牧人耶稣，照顾受苦的邻舍。即使相隔遥远，也愿我们一同持守盼望，朝着您应许的城前行。阿们。"},"handbook":{"today_focus":"群体要察看领袖生命的果子，并以永不改变的耶稣为中心。跟随城门外受苦的主，意味着不追逐安全的宗教荣耀，而以颂赞、善行、分享和与被排斥者同行，作为今天献给神的祭。","contextual_q":"","contextual_hint":"","textual_context":"","covenant_context":"","ssc_ref":"","observations":[{"question":"经文怎样教导信徒看待领袖？信徒最终应当以谁为信仰的中心？"},{"question":"\\"出到营外就了他去\\"与颂赞、行善和捐输有什么联系？"}],"meditations":[{"question":"我是否把某位领袖、组织传统或被认可的位置当作信仰中心？","hint":""},{"question":"我所参与的敬拜，怎样具体连接到帮助受苦者和分享所有？","hint":""},{"question":"这三十天中，哪一句话最留在心里？哪一个习惯需要继续？","hint":""}],"practices":["写下一句最触动你的话，以及一项未来三十天要继续的习惯。","选择一项颂赞、善行或分享，作为跟随耶稣的具体祭物。"],"prayer":"感谢神带领我走过这三十天。\\n求主使我以耶稣，而不是人的认可和制度、荣耀为中心。\\n求主装备我行各样善事，并在彼此相隔时仍与群体同行。"}}]`),a={greeting:{salutation:`亲爱的2SC弟兄姊妹：`,paragraphs:[`不知不觉，我们已经有一段时间不能面对面分享神的话了。但你们始终在我的祷告中。即使身处不同的城市和国家，只要我们一同读神的话，仰望同一位耶稣，就仍是在同一条路上彼此同行的人。`,`作为一位韩国宣教士，我把这些牧养书信写给你们------曾在中国与我一同建立基督身体的弟兄姊妹。虽然相隔遥远，我们仍能借着一同读经、分享生活，保持联系，继续作为一个群体生活。我不轻看你们在日常生活中承受的经济压力、人际关系的难处，以及持守信仰所付出的辛劳。我盼望与你们一同聆听《希伯来书》，看看这卷书怎样重新扶起疲惫的教会群体。`,`《希伯来书》没有明确交代作者是谁、写给哪个地区的人，也没有说明确切的写作时间。但通读全书，我们会发现，这是一篇劝勉的信息。收信的人早已听过福音，也在信仰道路上走了多年，却因外在压力和群体内部的疲惫而想要退后。本书按《希伯来书》的经文顺序，沿着作者引用圣经、展开比较、交织警告与安慰的论述，将内容分为三十个主题，帮助我们在思想、内心和行动上回应神的话。`,`《希伯来书》中有许多今天的读者不太熟悉的词语，例如天使、摩西、安息、麦基洗德、大祭司、会幕与血、约与祭物等。这些表达来自当时犹太人和跟随耶稣的群体共同熟悉的圣经与敬拜传统。因此，我们不能把某个词单独抽出来，立刻变成今天的一条教义。我们应当先看作者为什么再次引用某段旧约经文，又借着怎样的比较来劝服听众。`,`《希伯来书》中的比较与警告十分强烈。例如更美的事、一次献上、离弃以后不能重新悔改，以及烈火等说法，都是讲道中的语言，要唤回正在动摇的听众，催促他们作出回应。作者并非只在个别句子里语气严厉。他指出儿子高过天使和摩西，把麦基洗德的祭司职分与利未体系相比较，把地上的圣所和反复献上的祭与天上的圣所相对照，并让我们看见耶稣一次献上自己、顺从到底的道路。他也引导听众越过眼前的城，等候将来的城。若把这整体脉络拆开，变成一套自动说明救恩过程的公式，就会错过作者作这些比较的用意。`,`每天先慢慢读当天的经文，再把牧养书信读出声来。不必为了赶时间匆匆读完，可以按自己的节奏停下来思想。每篇书信都兼顾经文本身、历史背景、作者的论述、给当时听众的劝勉，以及今天的应用。每日默想之后附有牧者为弟兄姊妹献上的祷告，分享结束时可以一同诵读，回应当天的信息。也可以把领受的安慰和应许记在心里，带着感谢，按自己的处境向神祷告。有些日子，我们以悔改回应神的话；有些日子，是安静休息、忍耐等候；还有些日子，是去鼓励身边的人。`,`阅读这些书信时，神的话有时会照亮我们的生活，使我们改正错误；有时会安慰疲惫的心，让我们为一路走来的恩典感谢神。耐心听完一个人的话、承担一直拖延的责任、留意病人的实际需要、为邻舍带去一点平安，这些都是神话语所结的果子。有些问题不能立刻解决，这时信靠神的应许，安静休息并忍耐等候，同样是信心的回应。各地群体的规模和处境虽然不同，但只要我们借着耶稣亲近神，以爱心和善行彼此建立，神国的生命就会在其中成长。我在远方记念你们每一个人的名字，愿与你们一同走过这三十天。`],author:`P. J. L（韩国宣教士，从远方写给你们）`},angles:[{title:`1. 从当时盼望圣殿和以色列复兴的背景来读`,body:`要理解《希伯来书》，很重要的一点是留意当时犹太社会普遍存在的期待：盼望以色列民族和圣殿得到复兴。许多人盼望借着洁净的敬拜、真正的祭司、恢复的圣殿和圣城，使神的统治再次清楚显明。相信耶稣的犹太人也并非完全置身于这种期待之外。《使徒行传》21章记载，许多犹太信徒热心律法，保罗也参与洁净礼，进入圣殿。本书从这样的角度理解《希伯来书》的劝勉：当看得见的复兴热潮不断吸引教会时，作者呼吁信徒持守已经领受的耶稣之道。只要跟随耶稣忠信的道路，现在就可以来到神面前。`},{title:`2. 把比较和警告看作讲道中的劝服方式`,body:`《希伯来书》虽然以书信的形式结尾，但正文大部分更像一篇经过精心安排、要在众人面前宣读的讲道。何况、更美、一次、今天、让我们一同前来等表达反复出现，整卷书的结构本身也在劝服听众。作者让人看见，地上圣殿和利未祭司职分的权威并非终极权威，并把不属于利未家谱的麦基洗德、天上的圣所，以及在城门外受苦的耶稣放在中心。这条论述脉络，要把受圣殿复兴吸引的群体重新带回耶稣面前。因此，不能把反复献祭与一次献上的对比，立刻扩大为对历世历代一切祭礼和整个犹太教的笼统判断。我们应当在作者所提出的问题中理解这些话：这个群体究竟要向谁忠心到底？`},{title:`3. 把神的话带进群体的实际生活`,body:`读经时，不要先把熟悉的结论套在经文上。要先看作者引用的旧约经文原本是在什么处境中说的，又为什么此刻再次提起。然后再思想，亲近神、彼此关顾、坚持一同聚集的劝勉，今天应当怎样落实在人际关系中。应用经文不只是寻找自己的不足。我们也要在神的话中分辨：有什么需要回转，有什么恩典值得感谢，有什么安慰需要领受，有什么应许需要等候，又能向别人提供什么帮助。若要定下具体行动，可以写明要向谁、做什么、何时完成。但不要彼此评断或催逼，而要温柔地了解对方真正需要什么帮助。`}],usage_note:`每天先慢慢读当天的经文，再把牧养书信读出声来。不必为了赶时间匆匆读完，可以按自己的节奏停下来思想。阅读这些书信时，神的话有时会照亮我们的生活，使我们改正错误；有时会安慰疲惫的心，让我们为一路走来的恩典感谢神。`},o=i;function s(){return{...n,hasHandbook:!0,startDate:`2026-10-12`,contents:o,badgeMetas:r,intro:a}}var c=s();typeof document<`u`&&c.id===`hebrews`&&document.documentElement.classList.add(`plan-hebrews`);var l=[{id:e.id,name:e.name,badgeMetas:t},{id:n.id,name:n.name,badgeMetas:r}];function u(e,t){if(t.getTime()<e.getTime())return 0;let n=new Date(t.getFullYear(),t.getMonth(),t.getDate()),r=n.getDay();(r===0||r===6)&&n.setDate(n.getDate()-(r===6?1:2));let i=new Date(e.getFullYear(),e.getMonth(),e.getDate()),a=0;for(;i.getTime()<=n.getTime();){let e=i.getDay();e!==0&&e!==6&&a++,i.setDate(i.getDate()+1)}return a}function d(){let[e,t,n]=c.startDate.split(`-`).map(Number);if(!e)return 1;let r=new Date(e,t-1,n),i=new Date,a=u(r,new Date(i.getFullYear(),i.getMonth(),i.getDate()));return Math.max(1,Math.min(c.totalDays,a))}function f(){let e=new Date().getDay();return e===0||e===6}function p(e){return c.contents.find(t=>t.day===e)}export{d as a,f as i,c as n,e as o,p as r,l as t};